-- Ascend · question batch. Original questions, correct answers spread evenly across A–D.
-- Run in the Supabase SQL editor. Safe to re-run (existing ids are skipped).
insert into public.ascend_questions (id, subject, level, domain, skill, passage, data_table, question, choices, answer_index, accept, explanation, status, source, published_at) values
('mathl3_001', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'In the equation 4(ax − 3) = 12x − 12, a is a constant. If the equation has infinitely many solutions, what is the value of a?', '["−3", "12", "4", "3"]'::jsonb, 3, null, 'Distribute: 4ax − 12 = 12x − 12. For every x to work, 4a = 12, so a = 3.', 'published', 'import', now()),
('mathl3_002', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'If (3/4)x − 2/3 = 5/6, what is the value of x?', null, null, '["2"]'::jsonb, 'Multiply every term by 12: 9x − 8 = 10, so 9x = 18 and x = 2.', 'published', 'import', now()),
('mathl3_003', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'In the equation kx + 6 = 3x − 9, k is a constant. For which value of k does the equation have no solution?', '["−3", "3", "6", "0"]'::jsonb, 1, null, 'Rearranged: (k − 3)x = −15. If k = 3 the left side is 0, and 0 = −15 is never true, so there is no solution.', 'published', 'import', now()),
('mathl3_004', 'math', 3, 'Algebra', 'Linear functions', null, null, 'Line k in the xy-plane is perpendicular to the line 2x − 5y = 10 and passes through (4, 1). What is the y-intercept of line k?', '["(0, 11)", "(0, 4.4)", "(0, −9)", "(0, 2.6)"]'::jsonb, 0, null, '2x − 5y = 10 has slope 2/5, so k has slope −5/2. y − 1 = −(5/2)(x − 4) gives y = −(5/2)x + 11.', 'published', 'import', now()),
('mathl3_005', 'math', 3, 'Algebra', 'Linear functions', null, null, 'The function f is linear, f(2) = 7, and f(6) = −5. What is the value of f(0)?', null, null, '["13"]'::jsonb, 'The slope is (−5 − 7) ÷ (6 − 2) = −3. f(0) = f(2) − 2(−3) = 7 + 6 = 13.', 'published', 'import', now()),
('mathl3_006', 'math', 3, 'Algebra', 'Linear functions', null, null, 'A company''s profit P, in dollars, from selling n backpacks is P = 18n − 2,700. What is the least number of backpacks the company must sell to earn a profit of at least $1,800?', '["100", "500", "250", "150"]'::jsonb, 2, null, '18n − 2,700 ≥ 1,800 gives 18n ≥ 4,500, so n ≥ 250.', 'published', 'import', now()),
('mathl3_007', 'math', 3, 'Algebra', 'Linear functions', null, null, 'In the xy-plane, the graph of y = ax + b passes through (−3, 2) and (6, 8). What is the value of a + b?', '["14/3", "4", "16/3", "2/3"]'::jsonb, 0, null, 'a = (8 − 2) ÷ (6 + 3) = 2/3. Then 2 = (2/3)(−3) + b, so b = 4. a + b = 2/3 + 4 = 14/3.', 'published', 'import', now()),
('mathl3_008', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, '6x − 4y = 18
ax − 2y = 9

In the system, a is a constant. For which value of a does the system have infinitely many solutions?', '["−3", "6", "3", "12"]'::jsonb, 2, null, 'Dividing the first equation by 2 gives 3x − 2y = 9. The equations are identical when a = 3.', 'published', 'import', now()),
('mathl3_009', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, '5x + 3y = 29
2x − y = 5

What is the value of x + y?', null, null, '["7"]'::jsonb, 'From the second equation, y = 2x − 5. Substitute: 5x + 3(2x − 5) = 29, so 11x = 44, x = 4, and y = 3. x + y = 7.', 'published', 'import', now()),
('mathl3_010', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'A store sells small candles for $4 and large candles for $9. On Saturday it sold 85 candles for a total of $490. How many large candles were sold?', '["55", "25", "40", "30"]'::jsonb, 3, null, 's + l = 85 and 4s + 9l = 490. Substituting s = 85 − l: 340 + 5l = 490, so l = 30.', 'published', 'import', now()),
('mathl3_011', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'y = 3x − 7
y = −x + c

In the system, c is a constant. The solution is (x, y) where x = 4. What is the value of c?', '["1", "13", "5", "9"]'::jsonb, 3, null, 'When x = 4, y = 3(4) − 7 = 5. Then 5 = −4 + c, so c = 9.', 'published', 'import', now()),
('mathl3_012', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'Which point (x, y) is a solution to both y > 2x − 3 and y ≤ −x + 6?', '["(5, 2)", "(2, 3)", "(4, 4)", "(0, −4)"]'::jsonb, 1, null, 'For (2, 3): 3 > 1 is true and 3 ≤ 4 is true. Each other point fails at least one inequality.', 'published', 'import', now()),
('mathl3_013', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'A delivery truck weighs 9,800 pounds empty and may not cross a bridge if its total weight exceeds 15,000 pounds. Each crate weighs 65 pounds. What is the maximum number of crates the truck can carry across the bridge?', null, null, '["80"]'::jsonb, '9,800 + 65c ≤ 15,000 gives 65c ≤ 5,200, so c ≤ 80.', 'published', 'import', now()),
('mathl3_014', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x^{2} − 25)/(x^{2} + 2x − 15) for x ≠ −5 and x ≠ 3?', '["(x + 5)/(x + 3)", "(x − 5)/(x − 3)", "−5/3", "(x − 5)/(x + 3)"]'::jsonb, 1, null, 'x^{2} − 25 = (x − 5)(x + 5) and x^{2} + 2x − 15 = (x + 5)(x − 3). Cancel (x + 5).', 'published', 'import', now()),
('mathl3_015', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'If (ax + 3)(2x − b) = 6x^{2} − 3x − 9 for all values of x, where a and b are constants, what is the value of a + b?', '["−6", "9", "3", "6"]'::jsonb, 3, null, 'Expanding gives 2ax^{2} + (6 − ab)x − 3b. So 2a = 6 (a = 3) and −3b = −9 (b = 3). Check the x term: 6 − 9 = −3. a + b = 6.', 'published', 'import', now()),
('mathl3_016', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 8^{2/3}?', '["16/3", "4", "2", "64^{3}"]'::jsonb, 1, null, '8^{1/3} = 2, and 2^{2} = 4.', 'published', 'import', now()),
('mathl3_017', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'For x > 0, which expression is equivalent to √(50x^{3})?', '["5x√(2x)", "10x√(5x)", "25x√(2x)", "5x^{2}√2"]'::jsonb, 0, null, '50x^{3} = 25x^{2} · 2x, and √(25x^{2}) = 5x.', 'published', 'import', now()),
('mathl3_018', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'How many real solutions does 3x^{2} − 4x + 5 = 0 have?', '["Exactly one", "Zero", "Infinitely many", "Exactly two"]'::jsonb, 1, null, 'The discriminant is (−4)^{2} − 4(3)(5) = 16 − 60 = −44, which is negative, so there are no real solutions.', 'published', 'import', now()),
('mathl3_019', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'In the equation x^{2} + kx + 16 = 0, k is a positive constant. If the equation has exactly one real solution, what is the value of k?', null, null, '["8"]'::jsonb, 'Exactly one solution means the discriminant is 0: k^{2} − 64 = 0, so k = 8.', 'published', 'import', now()),
('mathl3_020', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the product of the solutions to 2x^{2} − 7x − 15 = 0?', '["−7.5", "7.5", "−15", "3.5"]'::jsonb, 0, null, 'Factor: (2x + 3)(x − 5) = 0, so x = −1.5 or x = 5. The product is −7.5 (also c/a = −15/2).', 'published', 'import', now()),
('mathl3_021', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'If √(2x + 11) = x + 4, what is the value of x?', '["−1", "1", "−5 and −1", "−5"]'::jsonb, 0, null, 'Square: 2x + 11 = x^{2} + 8x + 16, so x^{2} + 6x + 5 = 0 and x = −1 or x = −5. Check: x = −5 gives √1 = −1, which is false, so only x = −1 works.', 'published', 'import', now()),
('mathl3_022', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'y = x^{2} − 3x + 2
y = x − 1

What is the sum of the x-coordinates of the solutions to the system?', '["3", "2", "4", "5"]'::jsonb, 2, null, 'Set equal: x^{2} − 4x + 3 = 0, so (x − 1)(x − 3) = 0 and x = 1 or 3. The sum is 4.', 'published', 'import', now()),
('mathl3_023', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = 2(x − 3)^{2} − 8. What is the y-intercept of the graph of y = f(x)?', '["(0, 26)", "(0, −8)", "(0, 10)", "(0, 1)"]'::jsonb, 2, null, 'f(0) = 2(9) − 8 = 10.', 'published', 'import', now()),
('mathl3_024', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'A sample of a substance has a mass of 640 grams and loses half its mass every 5 years. Which function gives its mass, in grams, after t years?', '["M(t) = 640 − 5t/2", "M(t) = 640(1/2)^{t/5}", "M(t) = 640(5)^{−t/2}", "M(t) = 640(1/2)^{5t}"]'::jsonb, 1, null, 'The mass is multiplied by 1/2 once every 5 years, so after t years it has been halved t/5 times.', 'published', 'import', now()),
('mathl3_025', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function g is defined by g(x) = 1,200(1.05)^{x}. By what percent does g(x) increase when x increases by 2?', '["10%", "105%", "10.25%", "5%"]'::jsonb, 2, null, 'Increasing x by 2 multiplies g by 1.05^{2} = 1.1025, an increase of 10.25%.', 'published', 'import', now()),
('mathl3_026', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The graph of y = x^{2} − 6x + c in the xy-plane has its vertex on the x-axis. What is the value of c?', null, null, '["9"]'::jsonb, 'The vertex is at x = 3. For the vertex to be on the x-axis, 9 − 18 + c = 0, so c = 9.', 'published', 'import', now()),
('mathl3_027', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'If f(x) = x^{2} + 1 and g(x) = 2x − 3, what is f(g(3))?', '["10", "4", "17", "7"]'::jsonb, 0, null, 'g(3) = 3, and f(3) = 9 + 1 = 10.', 'published', 'import', now()),
('mathl3_028', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A car''s fuel efficiency is 32 miles per gallon. Gas costs $3.60 per gallon. What is the fuel cost, in dollars, of driving 440 miles?', '["55.00", "39.60", "49.50", "44.00"]'::jsonb, 2, null, '440 ÷ 32 = 13.75 gallons. 13.75 × 3.60 = 49.50.', 'published', 'import', now()),
('mathl3_029', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A density of 2.7 grams per cubic centimeter is equivalent to how many kilograms per cubic meter? (1 kg = 1,000 g; 1 m^{3} = 1,000,000 cm^{3})', null, null, '["2700", "2,700"]'::jsonb, '2.7 g/cm^{3} × 1,000,000 cm^{3}/m^{3} ÷ 1,000 g/kg = 2,700 kg/m^{3}.', 'published', 'import', now()),
('mathl3_030', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'Pipe A fills a tank in 6 hours, and pipe B fills it in 3 hours. How many hours does it take the two pipes working together to fill the tank?', '["2", "4.5", "9", "1.5"]'::jsonb, 0, null, 'Together they fill 1/6 + 1/3 = 1/2 of the tank per hour, so it takes 2 hours.', 'published', 'import', now()),
('mathl3_031', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'The price of a stock rose 25% on Monday and fell 20% on Tuesday. Compared with its price before Monday, the price after Tuesday is', '["45% higher", "5% lower", "5% higher", "the same"]'::jsonb, 3, null, '1.25 × 0.80 = 1.00, so the price is unchanged.', 'published', 'import', now()),
('mathl3_032', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A number p is 30% greater than q, and q is 20% less than r. What is p as a percent of r?', '["150%", "90%", "110%", "104%"]'::jsonb, 3, null, 'p = 1.3q and q = 0.8r, so p = 1.04r, which is 104% of r.', 'published', 'import', now()),
('mathl3_033', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A town''s population decreased by 12% from 2010 to 2020, to 13,200. What was the population in 2010?', null, null, '["15000", "15,000"]'::jsonb, '0.88 × P = 13,200, so P = 15,000.', 'published', 'import', now()),
('mathl3_034', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'Data set X: 10, 20, 30, 40, 50. Data set Y: 28, 29, 30, 31, 32. Which statement is true?', '["The sets have equal means, and X has a greater standard deviation", "The sets have equal means and equal standard deviations", "Y has a greater mean and a greater standard deviation", "X has a greater mean, and Y has a greater standard deviation"]'::jsonb, 0, null, 'Both means are 30. The values in X are much more spread out from 30, so X has the greater standard deviation.', 'published', 'import', now()),
('mathl3_035', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The mean score of 20 students on a quiz is 78. When one more student''s score is added, the mean becomes 79. What is the new student''s score?', '["80", "98", "99", "79"]'::jsonb, 2, null, 'The new total is 21 × 79 = 1,659. The old total is 20 × 78 = 1,560. The new score is 1,659 − 1,560 = 99.', 'published', 'import', now()),
('mathl3_036', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'Each value in a data set is increased by 5. Which of the following must also increase by 5?', '["The mean and the median", "The range", "The standard deviation", "The mean, median, and range"]'::jsonb, 0, null, 'Adding 5 to every value shifts the center up by 5 but doesn''t change the spread, so the range and standard deviation stay the same.', 'published', 'import', now()),
('mathl3_037', 'math', 3, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'For a set of cities, the line of best fit relating elevation x (in thousands of feet) to average July temperature y (°F) is y = −3.2x + 88. Which statement is the best interpretation of −3.2?', '["Cities lose 3.2°F every year", "For each additional 1,000 feet of elevation, the predicted temperature is 3.2°F lower", "The temperature at sea level is predicted to be −3.2°F", "Each city is 3.2°F cooler than the one before it"]'::jsonb, 1, null, 'The slope tells how much y changes for each 1-unit increase in x, and x is in thousands of feet.', 'published', 'import', now()),
('mathl3_038', 'math', 3, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'A data set is modeled by y = 150(0.9)^{x}. According to the model, what is y when x = 2?', '["135", "120", "121.5", "243"]'::jsonb, 2, null, '150 × 0.9 × 0.9 = 121.5.', 'published', 'import', now()),
('mathl3_039', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, '{"h": ["", "Mornings", "Evenings", "Total"], "r": [["Under 30", "20", "80", "100"], ["30 and over", "90", "60", "150"], ["Total", "110", "140", "250"]]}'::jsonb, 'A survey asked 250 people whether they prefer mornings or evenings.

If a person is chosen at random from those who prefer evenings, what is the probability that the person is under 30?', '["4/5", "4/7", "2/5", "3/5"]'::jsonb, 1, null, 'Of the 140 people who prefer evenings, 80 are under 30: 80/140 = 4/7.', 'published', 'import', now()),
('mathl3_040', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'Two fair coins are tossed. Given that at least one coin shows heads, what is the probability that both coins show heads?', '["1/2", "3/4", "1/3", "1/4"]'::jsonb, 2, null, 'The outcomes with at least one head are HH, HT, TH. Only HH has two heads: 1/3.', 'published', 'import', now()),
('mathl3_041', 'math', 3, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A random sample of 900 adults in a city found that 38% exercise daily, with a margin of error of 3%. Which statement is best supported?', '["Exactly 38% of adults in the city exercise daily", "No adults outside the sample exercise daily", "It is plausible that between 35% and 41% of adults in the city exercise daily", "A sample of 9,000 adults would have a larger margin of error"]'::jsonb, 2, null, 'The margin of error gives a plausible range of 38% ± 3%. Larger samples give smaller margins of error, not larger.', 'published', 'import', now()),
('mathl3_042', 'math', 3, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A researcher randomly assigned 200 volunteers to drink either green tea or water daily. The green tea group had lower average blood pressure after 3 months. Which conclusion is appropriate?', '["No conclusion is possible because the study was random", "Water raises blood pressure", "Green tea lowers blood pressure for every person", "Green tea likely caused lower blood pressure for people like these volunteers"]'::jsonb, 3, null, 'Random assignment supports a cause-and-effect conclusion, but only for the population the volunteers represent.', 'published', 'import', now()),
('mathl3_043', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'The equation x^{2} + y^{2} − 6x + 8y = 0 defines a circle in the xy-plane. What is the radius of the circle?', '["25", "4", "10", "5"]'::jsonb, 3, null, 'Complete the square: (x − 3)^{2} + (y + 4)^{2} = 9 + 16 = 25, so r = 5.', 'published', 'import', now()),
('mathl3_044', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has center (2, −1) and passes through (5, 3). Which equation represents the circle?', '["(x − 5)^{2} + (y − 3)^{2} = 25", "(x + 2)^{2} + (y − 1)^{2} = 25", "(x − 2)^{2} + (y + 1)^{2} = 5", "(x − 2)^{2} + (y + 1)^{2} = 25"]'::jsonb, 3, null, 'r^{2} = (5 − 2)^{2} + (3 + 1)^{2} = 9 + 16 = 25, and the center is (2, −1).', 'published', 'import', now()),
('mathl3_045', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'In a circle with radius 9, a sector has a central angle of 2π/3 radians. What is the area of the sector?', '["27π", "6π", "54π", "18π"]'::jsonb, 0, null, 'Sector area = (1/2)r^{2}θ = (1/2)(81)(2π/3) = 27π.', 'published', 'import', now()),
('mathl3_046', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In right triangle PQR, angle R is 90° and cos P = 0.6. What is tan P?', '["3/5", "4/3", "5/3", "3/4"]'::jsonb, 1, null, 'If cos P = 3/5, the side opposite P is 4 (a 3-4-5 triangle). tan P = 4/3.', 'published', 'import', now()),
('mathl3_047', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In a right triangle, sin x° = cos 32°. What is the value of x?', null, null, '["58"]'::jsonb, 'sin x° = cos(90° − x°), so 90 − x = 32 and x = 58.', 'published', 'import', now()),
('mathl3_048', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'A 30-60-90 triangle has a hypotenuse of 14. What is the length of the side opposite the 60° angle?', '["7√3", "14√3", "7√2", "7"]'::jsonb, 0, null, 'In a 30-60-90 triangle the short leg is half the hypotenuse (7), and the long leg is 7√3.', 'published', 'import', now()),
('mathl3_049', 'math', 3, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'In triangle ABC, point D is on AB and point E is on AC so that DE is parallel to BC. AD = 6, DB = 4, and DE = 9. What is BC?', '["13", "15", "6", "13.5"]'::jsonb, 1, null, 'Triangles ADE and ABC are similar with ratio AD/AB = 6/10. So 9/BC = 6/10 and BC = 15.', 'published', 'import', now()),
('mathl3_050', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A cone has a radius of 6 and a height of 8. What is its volume?', '["48π", "384π", "288π", "96π"]'::jsonb, 3, null, 'V = (1/3)πr^{2}h = (1/3)π(36)(8) = 96π.', 'published', 'import', now()),
('mathl3_051', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A sphere has a volume of 36π cubic units. What is its radius?', null, null, '["3"]'::jsonb, '(4/3)πr^{3} = 36π gives r^{3} = 27, so r = 3.', 'published', 'import', now()),
('mathl3_052', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangular box has a volume of 360 cubic inches. Its length is twice its width, and its height is 5 inches. What is the width, in inches?', '["12", "6", "5", "36"]'::jsonb, 1, null, '2w × w × 5 = 360, so 10w^{2} = 360, w^{2} = 36 and w = 6.', 'published', 'import', now()),
('mathl1b_001', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 6x + 4 = 40, what is the value of x?', '["6", "4", "7.3", "36"]'::jsonb, 0, null, 'Subtract 4: 6x = 36. Divide by 6: x = 6.', 'published', 'import', now()),
('mathl1b_002', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 2(x − 5) = 14, what is the value of x?', null, null, '["12"]'::jsonb, 'Divide by 2: x − 5 = 7, so x = 12.', 'published', 'import', now()),
('mathl1b_003', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 9 = 3x − 12, what is the value of x?', '["21", "−1", "3", "7"]'::jsonb, 3, null, 'Add 12: 21 = 3x, so x = 7.', 'published', 'import', now()),
('mathl1b_004', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 8x − 5 = 3x + 20, what is the value of x?', '["5", "25", "3.75", "3"]'::jsonb, 0, null, 'Subtract 3x: 5x − 5 = 20. Add 5: 5x = 25, so x = 5.', 'published', 'import', now()),
('mathl1b_005', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'Sam has $45 and saves $15 each week. After how many weeks will Sam have $150?', '["7", "13", "10", "3"]'::jsonb, 0, null, '45 + 15w = 150, so 15w = 105 and w = 7.', 'published', 'import', now()),
('mathl1b_006', 'math', 1, 'Algebra', 'Linear functions', null, null, 'The function p is defined by p(x) = 10 − 4x. What is the value of p(−2)?', '["18", "2", "−18", "6"]'::jsonb, 0, null, 'p(−2) = 10 − 4(−2) = 10 + 8 = 18.', 'published', 'import', now()),
('mathl1b_007', 'math', 1, 'Algebra', 'Linear functions', null, null, 'What is the slope of the line y = 7 − 2x?', '["7", "−7", "2", "−2"]'::jsonb, 3, null, 'Written as y = −2x + 7, the coefficient of x is −2.', 'published', 'import', now()),
('mathl1b_008', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A candle is 12 inches tall and burns 0.5 inch each hour. How tall, in inches, is the candle after 8 hours?', null, null, '["8"]'::jsonb, '12 − 0.5(8) = 12 − 4 = 8 inches.', 'published', 'import', now()),
('mathl1b_009', 'math', 1, 'Algebra', 'Linear functions', null, null, 'Which equation represents a line that passes through (0, −4) and has slope 3?', '["y = −4x + 3", "y = −3x − 4", "y = 3x + 4", "y = 3x − 4"]'::jsonb, 3, null, 'Slope-intercept form is y = mx + b with m = 3 and b = −4.', 'published', 'import', now()),
('mathl1b_010', 'math', 1, 'Algebra', 'Linear functions', null, null, 'The cost C, in dollars, to rent a kayak for h hours is C = 15h + 10. What is the cost of renting a kayak for 3 hours?', '["55", "75", "45", "28"]'::jsonb, 0, null, 'C = 15(3) + 10 = 55.', 'published', 'import', now()),
('mathl1b_011', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'a + b = 20
a − b = 6

What is the value of b?', '["7", "14", "6", "13"]'::jsonb, 0, null, 'Adding gives 2a = 26, so a = 13 and b = 20 − 13 = 7.', 'published', 'import', now()),
('mathl1b_012', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'Tickets to a fair cost $5 for children and $8 for adults. A group of 10 people paid $65. How many children were in the group?', '["4", "3", "5", "6"]'::jsonb, 2, null, 'c + a = 10 and 5c + 8a = 65. Then 5c + 80 − 8c = 65, so 3c = 15 and c = 5.', 'published', 'import', now()),
('mathl1b_013', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'y = x + 3
y = 2x − 1

What is the value of x?', null, null, '["4"]'::jsonb, 'Set equal: x + 3 = 2x − 1, so x = 4.', 'published', 'import', now()),
('mathl1b_014', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'Which value of x is NOT a solution to x − 7 < 2?', '["5", "9", "0", "8"]'::jsonb, 1, null, 'x − 7 < 2 means x < 9. Since 9 is not less than 9, it is not a solution.', 'published', 'import', now()),
('mathl1b_015', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'Mia needs at least 80 points to pass. She has 52 points and earns 4 points per correct answer. What is the least number of correct answers she needs?', '["7", "13", "20", "6"]'::jsonb, 0, null, '52 + 4n ≥ 80, so 4n ≥ 28 and n ≥ 7.', 'published', 'import', now()),
('mathl1b_016', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'Which inequality represents "a number n decreased by 3 is at most 10"?', '["3 − n ≤ 10", "n − 3 < 10", "n − 3 ≥ 10", "n − 3 ≤ 10"]'::jsonb, 3, null, '"Decreased by 3" is n − 3, and "at most" means less than or equal to.', 'published', 'import', now()),
('mathl1b_017', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 5x + 2(x − 4)?', '["7x − 4", "5x − 8", "7x − 8", "7x + 8"]'::jsonb, 2, null, 'Distribute: 5x + 2x − 8 = 7x − 8.', 'published', 'import', now()),
('mathl1b_018', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x^{3})^{2}?', '["x^{6}", "x^{5}", "x^{9}", "2x^{3}"]'::jsonb, 0, null, 'When raising a power to a power, multiply the exponents: 3 × 2 = 6.', 'published', 'import', now()),
('mathl1b_019', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 4x^{2} + 6x?', '["2(2x + 3)", "4x(x + 6)", "2x(2x + 3)", "x(4x + 6x)"]'::jsonb, 2, null, 'Factor out the greatest common factor, 2x: 2x(2x + 3).', 'published', 'import', now()),
('mathl1b_020', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'What are the solutions to x^{2} − 16 = 0?', '["x = 16 and x = −16", "x = 8 and x = −8", "x = 4 and x = −4", "x = 4 only"]'::jsonb, 2, null, 'x^{2} = 16, so x = 4 or x = −4.', 'published', 'import', now()),
('mathl1b_021', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'If x^{2} + 5 = 41 and x > 0, what is the value of x?', null, null, '["6"]'::jsonb, 'x^{2} = 36, so x = 6.', 'published', 'import', now()),
('mathl1b_022', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = 3x^{2} − 2. What is f(2)?', '["14", "34", "10", "4"]'::jsonb, 2, null, 'f(2) = 3(4) − 2 = 10.', 'published', 'import', now()),
('mathl1b_023', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'A town of 2,000 people grows by 10% each year. What is the population after 2 years?', '["2,200", "2,420", "4,000", "2,400"]'::jsonb, 1, null, '2,000 × 1.1 × 1.1 = 2,420.', 'published', 'import', now()),
('mathl1b_024', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'The graph of y = x^{2} − 4 crosses the x-axis at which points?', '["(2, 0) only", "(4, 0) and (−4, 0)", "(0, −4) only", "(2, 0) and (−2, 0)"]'::jsonb, 3, null, 'Set y = 0: x^{2} = 4, so x = 2 or x = −2.', 'published', 'import', now()),
('mathl1b_025', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A store sells 6 bottles of juice for $9. At this price, how much do 10 bottles cost, in dollars?', '["12", "18", "13.50", "15"]'::jsonb, 3, null, 'Each bottle costs 9 ÷ 6 = 1.50. 10 × 1.50 = 15.', 'published', 'import', now()),
('mathl1b_026', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A cyclist rides 36 miles in 3 hours. What is the cyclist''s average speed, in miles per hour?', null, null, '["12"]'::jsonb, '36 ÷ 3 = 12 miles per hour.', 'published', 'import', now()),
('mathl1b_027', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'The ratio of red to white roses in a garden is 4 : 5. There are 36 roses in all. How many are red?', '["9", "4", "16", "20"]'::jsonb, 2, null, 'There are 9 parts, so each part is 4 roses. Red is 4 parts: 16.', 'published', 'import', now()),
('mathl1b_028', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'How many minutes are in 2.5 hours?', '["150", "250", "125", "90"]'::jsonb, 0, null, '2.5 × 60 = 150 minutes.', 'published', 'import', now()),
('mathl1b_029', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'What is 40% of 65?', '["25", "26", "16", "39"]'::jsonb, 1, null, '0.40 × 65 = 26.', 'published', 'import', now()),
('mathl1b_030', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A restaurant bill is $60. Ben leaves an 18% tip. How much is the tip, in dollars?', null, null, '["10.8", "10.80"]'::jsonb, '0.18 × 60 = 10.80.', 'published', 'import', now()),
('mathl1b_031', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'There are 25 students in a class, and 9 of them walk to school. What percent of the students walk to school?', '["9%", "25%", "36%", "64%"]'::jsonb, 2, null, '9 ÷ 25 = 0.36, which is 36%.', 'published', 'import', now()),
('mathl1b_032', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The ages of five cousins are 7, 9, 12, 12, and 15. What is the median age?', '["9", "12", "15", "11"]'::jsonb, 1, null, 'The ages are in order, and the middle value is 12.', 'published', 'import', now()),
('mathl1b_033', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The mean of 6, 10, x, and 14 is 11. What is the value of x?', '["14", "15", "11", "12"]'::jsonb, 0, null, 'The total must be 4 × 11 = 44. 44 − (6 + 10 + 14) = 14.', 'published', 'import', now()),
('mathl1b_034', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'A data set has a minimum of 18 and a range of 27. What is the maximum?', null, null, '["45"]'::jsonb, 'Range = maximum − minimum, so maximum = 18 + 27 = 45.', 'published', 'import', now()),
('mathl1b_035', 'math', 1, 'Problem-Solving and Data Analysis', 'Two-variable data', null, '{"h": ["Hours", "Miles"], "r": [["2", "110"], ["3", "165"], ["4", "220"]]}'::jsonb, 'The table shows how far a car travels over time at a constant speed. How far does it travel in 5 hours?', '["330 miles", "225 miles", "250 miles", "275 miles"]'::jsonb, 3, null, 'The car travels 55 miles each hour (110 ÷ 2). In 5 hours: 55 × 5 = 275 miles.', 'published', 'import', now()),
('mathl1b_036', 'math', 1, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'As the temperature outside rises, a shop sells more ice cream. Which kind of relationship does this describe?', '["No association", "A positive association", "A constant association", "A negative association"]'::jsonb, 1, null, 'When one variable increases and the other also increases, the association is positive.', 'published', 'import', now()),
('mathl1b_037', 'math', 1, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A jar has 4 lemon, 6 cherry, and 10 grape candies. If one candy is picked at random, what is the probability it is lemon?', '["1/4", "1/5", "4/10", "2/5"]'::jsonb, 1, null, 'There are 20 candies, and 4 are lemon: 4/20 = 1/5.', 'published', 'import', now()),
('mathl1b_038', 'math', 1, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'The letters of the word MATH are written on cards and one card is chosen at random. What is the probability of choosing a vowel?', '["1/2", "1/3", "3/4", "1/4"]'::jsonb, 3, null, 'Only A is a vowel, so the probability is 1 out of 4.', 'published', 'import', now()),
('mathl1b_039', 'math', 1, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A random sample of 40 students found that 30 like the new cafeteria menu. A school has 600 students. About how many of them would you expect to like the menu?', '["570", "450", "400", "300"]'::jsonb, 1, null, '30/40 = 75%. 75% of 600 = 450.', 'published', 'import', now()),
('mathl1b_040', 'math', 1, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'To learn how many people in a town own pets, which method gives the most reliable results?', '["Asking people at a dog park", "Asking only the student''s friends", "Asking a random sample of town residents", "Asking people at a pet store"]'::jsonb, 2, null, 'A random sample represents the whole town; the other groups are more likely to own pets.', 'published', 'import', now()),
('mathl1b_041', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A square has a perimeter of 28 cm. What is its area, in square centimeters?', '["7", "49", "196", "28"]'::jsonb, 1, null, 'Each side is 28 ÷ 4 = 7, so the area is 7 × 7 = 49.', 'published', 'import', now()),
('mathl1b_042', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangular prism is 4 cm long, 3 cm wide, and 5 cm tall. What is its volume, in cubic centimeters?', null, null, '["60"]'::jsonb, 'V = 4 × 3 × 5 = 60.', 'published', 'import', now()),
('mathl1b_043', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A parallelogram has a base of 12 inches and a height of 7 inches. What is its area, in square inches?', '["19", "42", "84", "38"]'::jsonb, 2, null, 'Area = base × height = 12 × 7 = 84.', 'published', 'import', now()),
('mathl1b_044', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Two angles are complementary. One measures 34°. What is the measure of the other?', '["34°", "56°", "146°", "66°"]'::jsonb, 1, null, 'Complementary angles add to 90°: 90 − 34 = 56.', 'published', 'import', now()),
('mathl1b_045', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'In an equilateral triangle, what is the measure of each angle?', '["90°", "45°", "180°", "60°"]'::jsonb, 3, null, 'All three angles are equal and add to 180°, so each is 60°.', 'published', 'import', now()),
('mathl1b_046', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Two vertical angles are formed by intersecting lines. One measures 48°. What is the measure of the angle vertical to it?', '["42°", "132°", "48°", "312°"]'::jsonb, 2, null, 'Vertical angles are always equal.', 'published', 'import', now()),
('mathl1b_047', 'math', 1, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'A right triangle has a hypotenuse of 13 and one leg of 5. What is the other leg?', null, null, '["12"]'::jsonb, '5^{2} + b^{2} = 13^{2}, so b^{2} = 169 − 25 = 144 and b = 12.', 'published', 'import', now()),
('mathl1b_048', 'math', 1, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has a circumference of 18π. What is its radius?', '["36", "3", "18", "9"]'::jsonb, 3, null, 'C = 2πr, so 2r = 18 and r = 9.', 'published', 'import', now()),
('mathl1b_049', 'math', 1, 'Geometry and Trigonometry', 'Circles', null, null, 'A circular rug has a radius of 3 feet. What is its area, in square feet?', '["3π", "9π", "6π", "18π"]'::jsonb, 1, null, 'Area = πr^{2} = π(3)^{2} = 9π.', 'published', 'import', now()),
('mathl2b_001', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If 7 − 3(x − 2) = 4, what is the value of x?', '["1", "−3", "5", "3"]'::jsonb, 3, null, 'Distribute: 7 − 3x + 6 = 4, so 13 − 3x = 4, 3x = 9 and x = 3.', 'published', 'import', now()),
('mathl2b_002', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If x/4 − x/6 = 2, what is the value of x?', null, null, '["24"]'::jsonb, 'Multiply by 12: 3x − 2x = 24, so x = 24.', 'published', 'import', now()),
('mathl2b_003', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If 3a − 6 = 21, what is the value of a − 2?', '["11", "9", "7", "5"]'::jsonb, 2, null, '3a = 27, so a = 9 and a − 2 = 7.', 'published', 'import', now()),
('mathl2b_004', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'How many solutions does the equation 4(x − 1) = 4x + 3 have?', '["Zero", "Infinitely many", "Exactly two", "Exactly one"]'::jsonb, 0, null, '4x − 4 = 4x + 3 simplifies to −4 = 3, which is never true, so there are no solutions.', 'published', 'import', now()),
('mathl2b_005', 'math', 2, 'Algebra', 'Linear functions', null, null, 'A line passes through (1, 4) and (5, 16). Which equation represents the line?', '["y = 4x", "y = 3x + 1", "y = 3x + 4", "y = 12x − 8"]'::jsonb, 1, null, 'Slope = (16 − 4) ÷ (5 − 1) = 3. Then 4 = 3(1) + b, so b = 1.', 'published', 'import', now()),
('mathl2b_006', 'math', 2, 'Algebra', 'Linear functions', null, null, 'The temperature in a freezer is 20°F and drops 4°F every 15 minutes. What is the temperature, in °F, after 2 hours?', '["4", "−12", "−8", "12"]'::jsonb, 1, null, '2 hours is 8 fifteen-minute periods, so the temperature drops 32°F: 20 − 32 = −12.', 'published', 'import', now()),
('mathl2b_007', 'math', 2, 'Algebra', 'Linear functions', null, null, 'For the linear function h, h(0) = 5 and h(3) = 17. What is h(10)?', null, null, '["45"]'::jsonb, 'The slope is (17 − 5) ÷ 3 = 4, so h(x) = 4x + 5 and h(10) = 45.', 'published', 'import', now()),
('mathl2b_008', 'math', 2, 'Algebra', 'Linear functions', null, null, 'Which line is perpendicular to y = −(1/2)x + 3?', '["y = −2x + 3", "y = −(1/2)x − 7", "y = 2x − 7", "y = (1/2)x + 3"]'::jsonb, 2, null, 'Perpendicular slopes are negative reciprocals. The negative reciprocal of −1/2 is 2.', 'published', 'import', now()),
('mathl2b_009', 'math', 2, 'Algebra', 'Linear functions', null, null, 'An online video has 1,200 views and gains 350 views per day. Which equation gives the total views V after d days?', '["V = 350 + 1,200d", "V = 1,550d", "V = 1,200 − 350d", "V = 1,200 + 350d"]'::jsonb, 3, null, 'Start at 1,200 and add 350 for each day.', 'published', 'import', now()),
('mathl2b_010', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, '4x + y = 14
2x − 3y = 0

What is the value of y?', '["6", "2", "3", "1"]'::jsonb, 1, null, 'From the first equation, y = 14 − 4x. Then 2x − 3(14 − 4x) = 0, so 14x = 42, x = 3 and y = 2.', 'published', 'import', now()),
('mathl2b_011', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'A farmer has chickens and goats. There are 30 animals with a total of 84 legs. How many goats are there?', '["12", "18", "21", "8"]'::jsonb, 0, null, 'c + g = 30 and 2c + 4g = 84. Substituting c = 30 − g: 60 + 2g = 84, so g = 12.', 'published', 'import', now()),
('mathl2b_012', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'x + 2y = 11
3x + 2y = 21

What is the value of x?', null, null, '["5"]'::jsonb, 'Subtract the first equation from the second: 2x = 10, so x = 5.', 'published', 'import', now()),
('mathl2b_013', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'The sum of two numbers is 41 and their difference is 9. What is the larger number?', '["25", "32", "20.5", "16"]'::jsonb, 0, null, 'x + y = 41 and x − y = 9. Adding: 2x = 50, so x = 25.', 'published', 'import', now()),
('mathl2b_014', 'math', 2, 'Algebra', 'Linear inequalities', null, null, 'Which value of x satisfies 3 − 2x ≥ 11?', '["−3", "0", "−5", "4"]'::jsonb, 2, null, '−2x ≥ 8. Dividing by −2 flips the sign: x ≤ −4. Only −5 is less than or equal to −4.', 'published', 'import', now()),
('mathl2b_015', 'math', 2, 'Algebra', 'Linear inequalities', null, null, 'A phone plan charges $20 per month plus $0.05 per text. Kai wants his bill to be no more than $32. What is the greatest number of texts he can send?', null, null, '["240"]'::jsonb, '20 + 0.05t ≤ 32, so 0.05t ≤ 12 and t ≤ 240.', 'published', 'import', now()),
('mathl2b_016', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x + 4)(x − 7)?', '["x^{2} − 28", "x^{2} − 3x − 28", "x^{2} − 3x + 28", "x^{2} + 3x − 28"]'::jsonb, 1, null, 'x^{2} − 7x + 4x − 28 = x^{2} − 3x − 28.', 'published', 'import', now()),
('mathl2b_017', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is a factored form of 2x^{2} + 7x + 3?', '["(x + 1)(x + 3)", "2(x + 1)(x + 3)", "(2x + 3)(x + 1)", "(2x + 1)(x + 3)"]'::jsonb, 3, null, '(2x + 1)(x + 3) = 2x^{2} + 6x + x + 3 = 2x^{2} + 7x + 3.', 'published', 'import', now()),
('mathl2b_018', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (6x^{4}y^{2})/(2x^{2}y) for x ≠ 0 and y ≠ 0?', '["3x^{6}y^{3}", "4x^{2}y", "3x^{2}y", "3x^{2}y^{2}"]'::jsonb, 2, null, '6 ÷ 2 = 3, x^{4} ÷ x^{2} = x^{2}, and y^{2} ÷ y = y.', 'published', 'import', now()),
('mathl2b_019', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 9x^{2} − 4?', '["(3x − 2)^{2}", "(3x − 4)(3x + 1)", "(9x − 2)(x + 2)", "(3x − 2)(3x + 2)"]'::jsonb, 3, null, 'This is a difference of squares: (3x)^{2} − 2^{2} = (3x − 2)(3x + 2).', 'published', 'import', now()),
('mathl2b_020', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the negative solution to x^{2} − x − 12 = 0?', null, null, '["-3", "−3"]'::jsonb, 'Factor: (x − 4)(x + 3) = 0. The solutions are 4 and −3.', 'published', 'import', now()),
('mathl2b_021', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'If 3^{x + 1} = 81, what is the value of x?', '["2", "4", "3", "26"]'::jsonb, 2, null, '81 = 3^{4}, so x + 1 = 4 and x = 3.', 'published', 'import', now()),
('mathl2b_022', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'If (x − 2)^{2} = 25, which list gives all solutions?', '["3 and −7", "−3 and 7", "−23 and 27", "7 only"]'::jsonb, 1, null, 'x − 2 = 5 or x − 2 = −5, so x = 7 or x = −3.', 'published', 'import', now()),
('mathl2b_023', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'If 12/x = x/3 and x > 0, what is the value of x?', '["6", "9", "4", "36"]'::jsonb, 0, null, 'Cross-multiply: x^{2} = 36, so x = 6.', 'published', 'import', now()),
('mathl2b_024', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = (x + 1)(x − 5). What is the x-coordinate of the vertex of its graph?', '["−1", "5", "2", "3"]'::jsonb, 2, null, 'The zeros are −1 and 5. The vertex lies halfway between them: (−1 + 5) ÷ 2 = 2.', 'published', 'import', now()),
('mathl2b_025', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'An account starts with $500 and earns 4% interest compounded once a year. Which expression gives the balance after t years?', '["500(1.04)^{t}", "500(0.04)^{t}", "500 + 0.04t", "500(1.4)^{t}"]'::jsonb, 0, null, 'Each year the balance is multiplied by 1 + 0.04 = 1.04.', 'published', 'import', now()),
('mathl2b_026', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'The function g is defined by g(x) = 4 · 3^{x}. What is g(2)?', null, null, '["36"]'::jsonb, 'g(2) = 4 · 9 = 36.', 'published', 'import', now()),
('mathl2b_027', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'The graph of y = −x^{2} + 6x − 5 opens downward. What is the maximum value of y?', '["3", "5", "4", "9"]'::jsonb, 2, null, 'The vertex is at x = −6 ÷ (2 · −1) = 3. y = −9 + 18 − 5 = 4.', 'published', 'import', now()),
('mathl2b_028', 'math', 2, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A machine fills 240 bottles in 8 minutes. At this rate, how many bottles does it fill in 1 hour?', '["1,800", "2,400", "1,920", "1,440"]'::jsonb, 0, null, 'The rate is 240 ÷ 8 = 30 bottles per minute. 30 × 60 = 1,800.', 'published', 'import', now()),
('mathl2b_029', 'math', 2, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A model car is built at a scale of 1 : 24. The model is 7.5 inches long. How long is the real car, in feet? (12 inches = 1 foot)', '["15", "18", "7.5", "180"]'::jsonb, 0, null, 'Real length = 7.5 × 24 = 180 inches = 15 feet.', 'published', 'import', now()),
('mathl2b_030', 'math', 2, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'If 5 workers can paint a fence in 6 hours, how many hours would it take 3 workers working at the same rate?', null, null, '["10"]'::jsonb, 'The job takes 5 × 6 = 30 worker-hours. 30 ÷ 3 = 10 hours.', 'published', 'import', now()),
('mathl2b_031', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A bicycle costs $280 before an 8% sales tax. What is the total cost with tax, in dollars?', '["504.00", "300.80", "302.40", "288.00"]'::jsonb, 2, null, '280 × 1.08 = 302.40.', 'published', 'import', now()),
('mathl2b_032', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A store marks up the wholesale price of a lamp by 60% and sells it for $72. What was the wholesale price, in dollars?', '["115.20", "28.80", "43.20", "45"]'::jsonb, 3, null, '1.60 × w = 72, so w = 45.', 'published', 'import', now()),
('mathl2b_033', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'In a class of 32 students, 75% passed a test. How many students did not pass?', null, null, '["8"]'::jsonb, '25% did not pass: 0.25 × 32 = 8.', 'published', 'import', now()),
('mathl2b_034', 'math', 2, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'Seven runners finished a race in these times (minutes): 22, 25, 25, 27, 30, 31, 45. Which measure would change the most if the 45 were removed?', '["The mean", "The mode", "The median", "None of them would change"]'::jsonb, 0, null, '45 is an outlier. Removing it lowers the mean noticeably, while the median changes only slightly and the mode stays 25.', 'published', 'import', now()),
('mathl2b_035', 'math', 2, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'A data set of 10 values has a mean of 14. A value of 25 is added. What is the new mean?', '["14.5", "19.5", "39", "15"]'::jsonb, 3, null, 'The old total is 140. The new total is 165, and 165 ÷ 11 = 15.', 'published', 'import', now()),
('mathl2b_036', 'math', 2, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'For a group of students, the equation y = 2.4x + 50 models test score y after x hours of tutoring. According to the model, how many hours of tutoring predict a score of 86?', '["36", "12", "14.3", "15"]'::jsonb, 3, null, '86 = 2.4x + 50, so 2.4x = 36 and x = 15.', 'published', 'import', now()),
('mathl2b_037', 'math', 2, 'Problem-Solving and Data Analysis', 'Two-variable data', null, '{"h": ["Hour", "Bacteria"], "r": [["0", "100"], ["1", "200"], ["2", "400"], ["3", "800"]]}'::jsonb, 'The table shows the number of bacteria in a dish. Which type of model best fits the data?', '["Linear decrease", "Exponential growth", "Linear growth", "No pattern"]'::jsonb, 1, null, 'The count doubles each hour (multiplies by the same factor), which is exponential growth.', 'published', 'import', now()),
('mathl2b_038', 'math', 2, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, '{"h": ["", "Bus", "Car", "Walk"], "r": [["6th grade", "40", "35", "25"], ["7th grade", "60", "20", "20"]]}'::jsonb, 'The table shows how 200 students get to school.

If a student who takes the bus is chosen at random, what is the probability the student is in 7th grade?', '["3/10", "3/5", "2/5", "1/2"]'::jsonb, 1, null, 'There are 100 bus riders, and 60 of them are 7th graders: 60/100 = 3/5.', 'published', 'import', now()),
('mathl2b_039', 'math', 2, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'Two fair number cubes (1–6) are rolled. What is the probability that the sum is 7?', '["1/6", "1/12", "7/36", "1/36"]'::jsonb, 0, null, 'There are 36 equally likely outcomes, and 6 of them sum to 7: 6/36 = 1/6.', 'published', 'import', now()),
('mathl2b_040', 'math', 2, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A factory tests a random sample of 500 light bulbs and finds 6 defective. About how many defective bulbs would be expected in a shipment of 20,000?', '["120", "60", "600", "240"]'::jsonb, 3, null, '6/500 = 1.2%. 1.2% of 20,000 = 240.', 'published', 'import', now()),
('mathl2b_041', 'math', 2, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A survey of 50 randomly chosen voters and a survey of 1,000 randomly chosen voters both estimate support for a law. Which statement is most likely true?', '["Neither survey can be used to estimate support", "The survey of 1,000 voters has a smaller margin of error", "Both surveys have the same margin of error", "The survey of 50 voters is more accurate"]'::jsonb, 1, null, 'Larger random samples produce smaller margins of error.', 'published', 'import', now()),
('mathl2b_042', 'math', 2, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangular pool is 25 m long, 10 m wide, and 2 m deep. How many cubic meters of water does it hold when full?', '["250", "520", "37", "500"]'::jsonb, 3, null, 'V = 25 × 10 × 2 = 500.', 'published', 'import', now()),
('mathl2b_043', 'math', 2, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A trapezoid has bases of 8 and 14 and a height of 5. What is its area?', null, null, '["55"]'::jsonb, 'A = (1/2)(8 + 14)(5) = 55.', 'published', 'import', now()),
('mathl2b_044', 'math', 2, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'In triangle ABC, angle A is twice angle B, and angle C is 60°. What is the measure of angle A?', '["60°", "40°", "120°", "80°"]'::jsonb, 3, null, 'A + B = 120 and A = 2B, so 3B = 120, B = 40 and A = 80.', 'published', 'import', now()),
('mathl2b_045', 'math', 2, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'The exterior angle of a triangle at vertex C measures 130°. The interior angle at A measures 55°. What is the interior angle at B?', '["75°", "65°", "50°", "125°"]'::jsonb, 0, null, 'An exterior angle equals the sum of the two remote interior angles: 130 − 55 = 75.', 'published', 'import', now()),
('mathl2b_046', 'math', 2, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In right triangle XYZ, angle Z is 90°, XZ = 8, and YZ = 15. What is cos X?', '["8/15", "8/17", "17/8", "15/17"]'::jsonb, 1, null, 'XY = √(64 + 225) = 17. cos X = adjacent ÷ hypotenuse = 8/17.', 'published', 'import', now()),
('mathl2b_047', 'math', 2, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'An isosceles right triangle has legs of length 6. What is the length of the hypotenuse?', '["6", "12", "6√2", "36"]'::jsonb, 2, null, 'In a 45-45-90 triangle, the hypotenuse is a leg times √2.', 'published', 'import', now()),
('mathl2b_048', 'math', 2, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle in the xy-plane has center (−1, 4) and radius 3. Which equation represents it?', '["(x + 1)^{2} + (y − 4)^{2} = 3", "(x + 1)^{2} + (y − 4)^{2} = 9", "(x − 1)^{2} + (y − 4)^{2} = 9", "(x − 1)^{2} + (y + 4)^{2} = 9"]'::jsonb, 1, null, 'Use (x − h)^{2} + (y − k)^{2} = r^{2} with h = −1, k = 4, and r^{2} = 9.', 'published', 'import', now()),
('mathl2b_049', 'math', 2, 'Geometry and Trigonometry', 'Circles', null, null, 'A pizza with a 14-inch diameter is cut into 8 equal slices. What is the area of one slice, in square inches?', '["14π/8", "7π/4", "49π/8", "49π/4"]'::jsonb, 2, null, 'The radius is 7, so the whole pizza is 49π. One slice is 49π ÷ 8.', 'published', 'import', now()),
('rwl3_001', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Some scholars have proposed that the two medieval manuscripts were copied by the same scribe. The connection remains ____, however, since it rests on a single similarity in letterforms that could easily be explained by shared training.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["conspicuous", "robust", "deliberate", "tenuous"]'::jsonb, 3, null, 'The link rests on a single unconfirmed source, so it is weak or flimsy, which is what tenuous means.', 'published', 'import', now()),
('rwl3_002', 'rw', 3, 'Craft and Structure', 'Words in Context', 'When the satellite measurements of polar ice loss were released, glaciologists noted that they closely matched data gathered by teams on the ground. The two independent sources thus served to ____ each other''s findings.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["obscure", "contradict", "corroborate", "anticipate"]'::jsonb, 2, null, 'Independent data that agree with the earlier findings confirm them, which is what corroborate means.', 'published', 'import', now()),
('rwl3_003', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The critic''s review of the film was notably ____: she praised its striking cinematography and ambitious structure, yet she also argued that its characters were too thinly drawn to sustain the story''s emotional weight.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["hostile", "indifferent", "enthusiastic", "ambivalent"]'::jsonb, 3, null, 'The critic both praises and faults the film, showing mixed feelings, which is what ambivalent means.', 'published', 'import', now()),
('rwl3_004', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Although the engineers would have preferred to replace the aging aqueduct entirely, they adopted a more ____ approach, reinforcing its weakest sections with materials the city could afford within that year''s budget.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["idealistic", "pragmatic", "nostalgic", "arbitrary"]'::jsonb, 1, null, 'The engineers chose a solution based on what was practical and affordable, which is what pragmatic means.', 'published', 'import', now()),
('rwl3_005', 'rw', 3, 'Craft and Structure', 'Words in Context', 'After cheaper steam-powered printing presses became available in the 1830s, newspapers in the United States ____: by midcentury, thousands of titles were in circulation, many of them sold for just a penny.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["converged", "stagnated", "proliferated", "dwindled"]'::jsonb, 2, null, 'The number of newspapers rose sharply, which is what proliferated (increased rapidly) means.', 'published', 'import', now()),
('rwl3_006', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Early editors of Emily Dickinson''s poems often "corrected" her dashes and unusual capitalization. Modern scholars, by contrast, regard these ____ features as deliberate choices that are central to the poems'' rhythm and meaning.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["haphazard", "derivative", "conventional", "idiosyncratic"]'::jsonb, 3, null, 'Dickinson''s punctuation and capitalization were distinctive and personal, which is what idiosyncratic means.', 'published', 'import', now()),
('rwl3_007', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Researchers hope the new treatment will arrest the progression of the disease in its early stages, preventing the most severe symptoms from developing.', null, 'As used in the text, what does the word "arrest" most nearly mean?', '["halt", "attract", "capture", "seize"]'::jsonb, 0, null, 'The treatment stops the disease''s progress, so "arrest" means halt.', 'published', 'import', now()),
('rwl3_008', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The plain, rounded shells of chambered nautiluses ____ the complexity within: each shell contains a series of gas-filled chambers that the animal adjusts to control its depth in the water.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["explain", "belie", "confirm", "exaggerate"]'::jsonb, 1, null, 'The plain appearance hides the complexity inside, so the exterior gives a false impression, which is what belie means.', 'published', 'import', now()),
('rwl3_009', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Rachel Carson''s 1962 book Silent Spring, which documented the harm caused by certain pesticides, ____ a generation of readers, many of whom went on to campaign for new environmental protections.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["distracted", "discouraged", "galvanized", "pacified"]'::jsonb, 2, null, 'The report spurred people into action, which is what galvanized means.', 'published', 'import', now()),
('rwl3_010', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Analyzing twenty years of data from forests in Ontario, researchers found that trees growing near rivers recovered from drought significantly faster than trees on higher ground. They concluded that access to groundwater plays a key role in forest resilience. The researchers acknowledge, though, that their sites shared a similar climate and soil type, so the pattern may not hold in other regions.', null, 'Which choice best describes the function of the final sentence in the overall structure of the text?', '["It qualifies the researchers'' conclusion by noting a limitation of the study", "It summarizes the methods used in the study", "It provides additional evidence that strengthens the conclusion", "It introduces an alternative hypothesis that the researchers rejected"]'::jsonb, 0, null, 'The last sentence points out that the study was limited to one region, which narrows how far the conclusion can be applied.', 'published', 'import', now()),
('rwl3_011', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'For decades, Henrietta Swan Leavitt was described in histories of astronomy as a diligent assistant who merely cataloged stars. Recent examination of her notebooks, however, shows that she independently recognized the relationship between the brightness and pulsation period of certain stars in 1912, a discovery that later allowed astronomers to measure distances to other galaxies.', null, 'Which choice best states the main purpose of the text?', '["To explain how a long-standing assumption about a historical figure was revised by new evidence", "To argue that historians should not rely on letters as evidence", "To describe the daily routine of a nineteenth-century astronomer", "To compare two competing theories about the structure of stars"]'::jsonb, 0, null, 'The text describes the earlier view of Henrietta Leavitt as a mere assistant and how archival evidence changed that view.', 'published', 'import', now()),
('rwl3_012', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Humpback whales in the South Pacific periodically abandon their songs and adopt entirely new ones, a change that spreads eastward across populations over a few years. Biologist Ellen Garland has argued that the songs are learned culturally, passed from whale to whale much as fashions spread among people. Supporting this idea, recordings show that a new song typically appears first in a western population and only later in populations farther east.', null, 'Which choice best describes the overall structure of the text?', '["It presents a puzzle, describes a proposed explanation, and then notes evidence supporting that explanation", "It narrates a scientist''s career in chronological order", "It summarizes two opposing views and concludes that both are incorrect", "It describes an experiment and then lists its practical applications"]'::jsonb, 0, null, 'The text opens with a puzzle (why the songs change), offers the cultural-transmission explanation, and ends with supporting evidence.', 'published', 'import', now()),
('rwl3_013', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Small apartments, the author argues, can offer residents a higher quality of life in crowded cities. Critics may object that such units feel cramped, but well-designed shared spaces, such as rooftop gardens and community kitchens, can more than compensate for limited private square footage. In several Tokyo developments, residents reported greater satisfaction than in larger units elsewhere.', null, 'Which choice best describes the function of the second sentence in the overall structure of the text?', '["It provides a historical example of the author''s claim", "It anticipates an objection to the author''s claim and responds to it", "It shifts the discussion to an unrelated topic", "It defines a term used in the first sentence"]'::jsonb, 1, null, 'The second sentence raises the objection that tiny homes are cramped and then answers it.', 'published', 'import', now()),
('rwl3_014', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
New Caledonian crows shape twigs into hooks to extract insects from tree bark. Because crows raised in captivity without adult models still attempt to manipulate twigs, some researchers conclude that the behavior is largely instinctive.

Text 2
Although captive crows handle twigs, their tools are crude compared with those made by wild crows. Field studies show that juvenile crows spend months near their parents, observing and even using the adults'' discarded tools. Their skill appears to depend heavily on what they learn from others.', null, 'Based on the texts, how would the author of Text 2 most likely respond to the conclusion in Text 1?', '["By claiming that the birds do not actually use tools", "By suggesting that the experiment should be repeated with mammals", "By arguing that the conclusion overlooks the role of social learning in the birds'' behavior", "By agreeing that the behavior is entirely instinctive"]'::jsonb, 2, null, 'Text 1 says the behavior is instinctive; Text 2 presents evidence that young birds learn it by watching adults.', 'published', 'import', now()),
('rwl3_015', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Some city planners now rely on large data sets, such as anonymous cell-phone location records, to decide where to build new transit lines. These data reveal travel patterns with a precision that surveys cannot match.

Text 2
Data on where people travel can be valuable, but it cannot reveal why they travel or which trips they avoid because they feel unsafe or unwelcome. Planners who skip conversations with residents risk building systems that serve existing patterns while ignoring unmet needs.', null, 'Which choice best describes how the author of Text 2 would most likely view the approach described in Text 1?', '["As useful but incomplete, because it ignores how residents actually experience their neighborhoods", "As entirely misguided, because data should never inform urban planning", "As identical to the approach the author recommends", "As superior to all other methods of planning cities"]'::jsonb, 0, null, 'Text 2 values data but argues planners must also listen to residents, so it would see Text 1''s approach as incomplete.', 'published', 'import', now()),
('rwl3_016', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'Floating mats of Sargassum seaweed have long provided shelter for young sea turtles, fish, and crabs in the open Atlantic. Since 2011, however, satellite images have revealed enormous blooms stretching thousands of miles. When these mats wash ashore in the Caribbean, they rot, release foul-smelling gases, smother coral and seagrass, and drive away tourists. Researchers suspect that nutrients from fertilizer runoff are fueling the growth.', null, 'Which choice best states the main idea of the text?', '["Fertilizer use has decreased in the regions bordering the Atlantic Ocean", "Sargassum seaweed is the only habitat available for young sea turtles", "Scientists have found an effective method of removing seaweed from beaches", "Sargassum seaweed, once valued as a habitat, has grown so abundant that it now causes environmental and economic harm"]'::jsonb, 3, null, 'The passage contrasts Sargassum''s traditional role as habitat with recent massive blooms that harm beaches, wildlife, and tourism.', 'published', 'import', now()),
('rwl3_017', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'Standard economic models predicted that raising the minimum wage would lead employers to cut jobs. In a widely discussed 1994 study, however, economists David Card and Alan Krueger compared fast-food restaurants in New Jersey, which had raised its minimum wage, with those in neighboring Pennsylvania, which had not. They found no evidence that employment fell in New Jersey relative to Pennsylvania.', null, 'According to the text, why did the economist''s findings surprise other researchers?', '["They showed that restaurants paid workers more than the minimum wage", "They relied on data from only one restaurant", "They showed that a higher minimum wage did not reduce employment as expected", "They found that prices fell after the wage increase"]'::jsonb, 2, null, 'Researchers expected higher wages to reduce jobs, but the study found employment did not fall.', 'published', 'import', now()),
('rwl3_018', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'The following text is adapted from a short story.

The house leaned slightly toward the river, as though it had been listening to the water for a hundred years. Its windows rattled in every storm, and the kitchen floor sagged in a way that sent marbles rolling toward the stove. Lucía knew every draft and creak by heart, and she would not have traded a single one of them for the sleek new apartments rising across town.', null, 'Based on the text, what is the narrator''s attitude toward the old house?', '["Indifferent, because she rarely visited it", "Affectionate, despite her awareness of its flaws", "Resentful, because it was difficult to maintain", "Fearful, because of strange noises at night"]'::jsonb, 1, null, 'The narrator lists the house''s flaws (drafty, sagging floors) but describes them fondly and says she would not trade it.', 'published', 'import', now()),
('rwl3_019', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'Researchers attached tiny tracking tags to honeybees to test whether low doses of a common pesticide impair the bees'' ability to navigate home. They concluded that the pesticide significantly reduced the bees'' homing ability.', '{"h": ["Group", "Bees tagged", "Returned to hive (%)"], "r": [["Exposed to pesticide", "300", "61"], ["Not exposed", "300", "92"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the researchers'' conclusion?', '["Bees exposed to the pesticide returned to the hive at a rate of 61 percent, compared with 92 percent for unexposed bees", "The study tracked bees over a period of four weeks", "Bees in both groups visited flowers during the study", "Unexposed bees returned to the hive at a rate of 92 percent"]'::jsonb, 0, null, 'The conclusion is that the pesticide impairs navigation, so the evidence must compare return rates for exposed and unexposed bees.', 'published', 'import', now()),
('rwl3_020', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'A historian argues that the rapid spread of lightweight printed cotton clothing in late-seventeenth-century Britain was driven mainly by the growing availability of imported Indian textiles.', null, 'Which finding, if true, would most strongly support the historian''s claim?', '["British wool production remained steady for the next century", "Portraits from the period show women wearing silk dresses", "Some British writers criticized the new fashion as wasteful", "Merchant records from the period show a sharp rise in shipments of cotton cloth from India to Britain just before the fashion changed"]'::jsonb, 3, null, 'The claim is that Indian cotton imports drove the fashion change, so evidence linking the timing of imports to the change supports it best.', 'published', 'import', now()),
('rwl3_021', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'In the poem "Harbor Song," the speaker expresses persistent hope despite repeated loss.', null, 'Which quotation from the poem most effectively illustrates the claim?', '["\"Salt hung heavy in the morning air.\"", "\"The gulls cried loud above the harbor wall.\"", "\"The fishing nets lay drying in the sun.\"", "\"I counted the ships that would not come back, / and still I watched the line where the sea meets sky.\""]'::jsonb, 3, null, 'The claim is about enduring hope despite loss; only this quotation shows both loss (ships that won''t return) and continued watching.', 'published', 'import', now()),
('rwl3_022', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'A student analyzed a graph from a national survey showing average nightly sleep for students ages 13 to 18. The graph shows that average sleep was about 8.5 hours at age 13 and decreased steadily with each year, reaching about 6.9 hours at age 18. The student concluded that teenagers tend to sleep less as they get older.', null, 'Which choice best describes data from the graph that support the student''s conclusion?', '["Students of all ages reported sleeping at least 6 hours", "Average sleep fell from about 8.5 hours among 13-year-olds to about 6.9 hours among 18-year-olds", "13-year-olds slept about 8.5 hours on average", "The survey included students from 40 schools"]'::jsonb, 1, null, 'The conclusion is that sleep declines with age; only this choice compares the youngest and oldest groups to show the decline.', 'published', 'import', now()),
('rwl3_023', 'rw', 3, 'Information and Ideas', 'Inferences', 'In 1971, biologists moved five pairs of Italian wall lizards, which mainly eat insects, to the Croatian island of Pod Mrčaru. When researchers returned decades later, they found that the lizards'' descendants ate large amounts of tough plant material and had larger heads and stronger bites than lizards on the original island. This suggests that ____', null, 'Which choice most logically completes the text?', '["the island''s lizards may have evolved larger heads in response to the new food source", "the researchers made errors in their measurements", "the lizards were unable to survive on the island", "plant-eating lizards are always smaller than insect-eating lizards"]'::jsonb, 0, null, 'The lizards switched to tough plants and developed stronger bites and bigger heads, suggesting evolution in response to diet.', 'published', 'import', now()),
('rwl3_024', 'rw', 3, 'Information and Ideas', 'Inferences', 'At an archaeological site in Texas, researchers found mammoth bones with narrow, V-shaped cuts. The cuts appear in consistent locations where muscles attach to bone, and their shape matches cuts produced experimentally with stone blades. Scratches made by trampling or by predators'' teeth, in contrast, tend to be irregular and shallow. The researchers therefore argue that ____', null, 'Which choice most logically completes the text?', '["the bones belonged to an animal that never existed", "the tool marks were probably made by people rather than by natural processes", "the site was occupied only in the last century", "the animals died of natural causes far from the site"]'::jsonb, 1, null, 'Cuts in regular patterns that match stone tools and appear where meat would be removed point to human butchering.', 'published', 'import', now()),
('rwl3_025', 'rw', 3, 'Information and Ideas', 'Inferences', 'Literary scholars comparing two editions of a nineteenth-century travel book found that almost none of the changes corrected spelling or factual mistakes. Instead, most revisions softened the author''s earlier criticism of the communities she had visited and added passages praising their customs. This suggests that ____', null, 'Which choice most logically completes the text?', '["both editions are identical", "the first edition was never published", "the author''s revisions may reflect a change in her views rather than an effort to fix errors", "the author did not write the second edition"]'::jsonb, 2, null, 'The changes alter the book''s argument, not its typos, so they suggest the author changed her mind.', 'published', 'import', now()),
('rwl3_026', 'rw', 3, 'Information and Ideas', 'Inferences', 'Algae in a mountain lake grow much more slowly at a depth of 10 meters than near the surface. A researcher assumed that the reduced sunlight at greater depths was responsible. However, when she lowered underwater lamps to 10 meters to provide as much light as at the surface, the algae there still grew slowly. This result suggests that ____', null, 'Which choice most logically completes the text?', '["the lake contains no algae at all", "sunlight has no effect on algae", "factors other than sunlight may limit the growth of the algae in deeper water", "the algae grow faster in deeper water"]'::jsonb, 2, null, 'Adding light to deep water did not increase growth, so something else, such as nutrients or temperature, must be limiting it.', 'published', 'import', now()),
('rwl3_027', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The museum''s new exhibit features journals from three polar explorers: Matthew Henson, who reached the North Pole region in ____ Roald Amundsen, the first person to reach the South Pole; and Ann Bancroft, who led the first all-women expedition to the South Pole.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1909,", "1909", "1909:", "1909;"]'::jsonb, 3, null, 'The items in this list contain their own commas, so semicolons must separate the items.', 'published', 'import', now()),
('rwl3_028', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The team published its ____ were later confirmed by laboratories in Japan and Brazil, in a leading physics journal.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["results. Which", "results; which", "results, which", "results which"]'::jsonb, 2, null, 'The clause beginning with "which" adds nonessential information about the results, so it is set off with a comma.', 'published', 'import', now()),
('rwl3_029', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Drawing on a looped-wire technique she learned from basket weavers in ____ created hanging sculptures from woven wire.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Mexico. Ruth Asawa", "Mexico, Ruth Asawa", "Mexico; Ruth Asawa", "Mexico Ruth Asawa"]'::jsonb, 1, null, 'The introductory phrase "Drawing on…Mexico" describes Asawa and must be followed by a comma, not a period or semicolon.', 'published', 'import', now()),
('rwl3_030', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The firefly''s glow is remarkably efficient. Nearly all of the energy in the chemical reaction becomes ____ produces very little heat compared with an incandescent bulb.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["light, it", "light: it", "light, and, it", "light it"]'::jsonb, 1, null, 'A colon can join two complete sentences when the second explains the first; a comma alone would create a comma splice.', 'published', 'import', now()),
('rwl3_031', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'In her 1956 study of chimpanzees in captivity, the psychologist ____ that the animals solved problems more quickly when they could watch one another work.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["observed;", "observed", "observed:", "observed,"]'::jsonb, 1, null, 'No punctuation belongs between a verb and its object ("that…").', 'published', 'import', now()),
('rwl3_032', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The world''s largest stores of fresh water—the Antarctic and Greenland ice sheets and thousands of mountain ____ are shrinking as average temperatures rise.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["glaciers;", "glaciers,", "glaciers", "glaciers—"]'::jsonb, 3, null, 'The interrupting phrase began with a dash, so it must end with a dash.', 'published', 'import', now()),
('rwl3_033', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'The series of paintings that Jacob Lawrence created to depict the Great Migration ____ first exhibited in 1941.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["was", "have been", "are", "were"]'::jsonb, 0, null, 'The subject is "the series" (singular), not "paintings," so the verb is "was."', 'published', 'import', now()),
('rwl3_034', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', '____ the endangered language for more than a decade, the linguist published the first comprehensive dictionary of its vocabulary.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["to study", "who studies", "studied", "having studied"]'::jsonb, 3, null, '"Having studied" creates an introductory phrase that correctly modifies the subject "the linguist."', 'published', 'import', now()),
('rwl3_035', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'Beneath the streets of Mexico City ____ the remains of Tenochtitlan, the capital of the Aztec Empire.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["lie", "laying", "lies", "lay"]'::jsonb, 0, null, 'The subject "the remains" is plural and the action is present, so "lie" is correct.', 'published', 'import', now()),
('rwl3_036', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'Neither the scientists nor the engineers expected ____ prototype to survive the first round of testing.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["his", "her", "its", "their"]'::jsonb, 3, null, '"Neither the scientists nor the engineers": the verb and pronoun agree with the nearer subject, "engineers" (plural).', 'published', 'import', now()),
('rwl3_037', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'When a metal detectorist uncovered the gold coin in 2019, experts determined that it ____ buried for nearly 1,200 years.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["had been", "is", "has been", "will be"]'::jsonb, 0, null, 'The coin had been buried before the time it was found (a past event), so the past perfect is correct.', 'published', 'import', now()),
('rwl3_038', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'The award goes each year to the young scientist to ____ the judges attribute the most original research.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["whom", "who", "whose", "which"]'::jsonb, 0, null, 'The pronoun is the object of the preposition "to," so "whom" is correct.', 'published', 'import', now()),
('rwl3_039', 'rw', 3, 'Expression of Ideas', 'Transitions', 'When Seoul tore down an elevated highway in 2003 to restore the stream that had flowed beneath it, many residents predicted traffic chaos. ____ traffic in the area improved, as drivers shifted to public transit and other routes.', null, 'Which choice completes the text with the most logical transition?', '["Paradoxically,", "Similarly,", "For example,", "Consequently,"]'::jsonb, 0, null, 'It is surprising that removing roads reduced traffic; "Paradoxically" signals a seemingly contradictory result.', 'published', 'import', now()),
('rwl3_040', 'rw', 3, 'Expression of Ideas', 'Transitions', 'Many plants in fire-prone regions are pyrophytic. ____ they have adapted to fire and in some cases even depend on it; certain pine cones, for instance, open and release seeds only after exposure to intense heat.', null, 'Which choice completes the text with the most logical transition?', '["Previously,", "Nevertheless,", "That is,", "Meanwhile,"]'::jsonb, 2, null, 'The second sentence restates and clarifies the first, so "That is" fits.', 'published', 'import', now()),
('rwl3_041', 'rw', 3, 'Expression of Ideas', 'Transitions', 'The early study of the vaccine included only a few hundred participants, and it ran for just six months. ____ its results were promising enough to justify a much larger trial.', null, 'Which choice completes the text with the most logical transition?', '["Thus,", "Specifically,", "Still,", "Moreover,"]'::jsonb, 2, null, 'The study had flaws, yet its finding was valuable; "Still" introduces that concession.', 'published', 'import', now()),
('rwl3_042', 'rw', 3, 'Expression of Ideas', 'Transitions', 'A ten-year study found that students who began school later in the morning got more sleep and earned higher grades. ____ several districts in the state pushed back their high school start times.', null, 'Which choice completes the text with the most logical transition?', '["Conversely,", "Accordingly,", "Regardless,", "Likewise,"]'::jsonb, 1, null, 'The policy change follows logically from the finding, so "Accordingly" fits.', 'published', 'import', now()),
('rwl3_043', 'rw', 3, 'Expression of Ideas', 'Transitions', 'When the body overheats, blood vessels near the skin widen, allowing heat to escape. ____ in cold conditions, those vessels narrow, keeping warm blood closer to the body''s core.', null, 'Which choice completes the text with the most logical transition?', '["Additionally,", "Conversely,", "Thereafter,", "Accordingly,"]'::jsonb, 1, null, 'The second sentence describes the opposite situation (heat vs. cold), so "Conversely" fits.', 'published', 'import', now()),
('rwl3_044', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Ada Lovelace (1815–1852) was the daughter of the poet Lord Byron.
• Charles Babbage designed a mechanical computer called the Analytical Engine.
• In 1843, Lovelace translated an article about it and added extensive notes.
• Her notes included an algorithm for the machine to calculate numbers.
• It is widely considered the first published computer program.
• Modern electronic computers appeared about a century later.', null, 'The student wants to emphasize the significance of Lovelace''s contribution. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Ada Lovelace was the daughter of the poet Lord Byron.", "Charles Babbage designed a machine called the Analytical Engine.", "Ada Lovelace''s 1843 notes included what is widely considered the first published computer program, written a century before modern computers existed.", "Ada Lovelace translated an article about Charles Babbage''s Analytical Engine."]'::jsonb, 2, null, 'Only this choice explains why her work mattered: it was the first program, far ahead of its time.', 'published', 'import', now()),
('rwl3_045', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Svalbard Global Seed Vault is in Norway, inside a mountain.
• It stores more than one million seed samples frozen at about −18°C.
• Community seed libraries lend seeds to local gardeners.
• Gardeners grow the plants and return new seeds at the end of the season.
• Both aim to preserve plant diversity.', null, 'The student wants to contrast the two approaches to preserving seeds. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Community seed libraries exist in many cities.", "Both seed banks and seed libraries aim to preserve plant diversity.", "The Svalbard Global Seed Vault is located in Norway.", "While the Svalbard vault stores seeds frozen in a single protected facility, community seed libraries keep varieties alive by having local gardeners grow and share them each year."]'::jsonb, 3, null, 'This choice states how each approach works and uses "while" to contrast them.', 'published', 'import', now()),
('rwl3_046', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Researchers studied 600 adults for one year.
• Participants wore step counters every day.
• Those who averaged about 7,000 steps a day had lower rates of heart disease.
• Benefits leveled off above about 10,000 steps.', null, 'The student wants to present the study''s method and its main finding. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Researchers studied 600 adults for one year.", "By tracking 600 participants who wore step counters for a year, researchers found that those who walked about 7,000 steps daily had lower rates of heart disease than those who walked fewer.", "Participants wore step counters, and some walked more than others.", "Walking is a popular form of exercise around the world."]'::jsonb, 1, null, 'Only this choice includes both how the study was done and what it found.', 'published', 'import', now()),
('rwl1b_001', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Mountain guides need boots that are extremely ____. A good pair must survive years of rocky trails, deep snow, and icy streams without falling apart.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["costly", "colorful", "durable", "flimsy"]'::jsonb, 2, null, 'Boots that last for years of hard use are durable, meaning long-lasting.', 'published', 'import', now()),
('rwl1b_002', 'rw', 1, 'Craft and Structure', 'Words in Context', 'The Pacific Ocean is so ____ that it covers more than 60 million square miles, more than all of Earth''s land put together.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["tiny", "vast", "shallow", "crowded"]'::jsonb, 1, null, 'An ocean covering more than 60 million square miles is enormous, which is what vast means.', 'published', 'import', now()),
('rwl1b_003', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Lin was ____ as she crossed the frozen pond. She tapped the ice with a stick before each step and stayed close to the shore.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["boastful", "sleepy", "cautious", "careless"]'::jsonb, 2, null, 'Checking the ice carefully before stepping on it shows that Lin was being careful, or cautious.', 'published', 'import', now()),
('rwl1b_004', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Some kinds of bamboo show ____ growth: under the right conditions, a stalk can grow as much as three feet in a single day.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["uncertain", "rapid", "silent", "gradual"]'::jsonb, 1, null, 'Growing up to three feet in a single day is extremely fast, or rapid.', 'published', 'import', now()),
('rwl1b_005', 'rw', 1, 'Craft and Structure', 'Words in Context', 'During the festival, residents hang thousands of paper lanterns to ____ the old town''s narrow streets after sunset.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["decorate", "darken", "measure", "illuminate"]'::jsonb, 3, null, 'Lanterns are used to light up the streets, which is what illuminate means.', 'published', 'import', now()),
('rwl1b_006', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Teachers described Katherine Johnson as an unusually bright student. She learned quickly and was taking high school classes by the age of ten.', null, 'As used in the text, what does the word "bright" most nearly mean?', '["cheerful", "colorful", "intelligent", "shining"]'::jsonb, 2, null, 'The text describes a student who learns quickly and solves hard problems, so "bright" means intelligent.', 'published', 'import', now()),
('rwl1b_007', 'rw', 1, 'Craft and Structure', 'Words in Context', 'In the dry season, water becomes ____ on the African savanna, and elephants may walk many miles each day to find a river or watering hole.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["frozen", "scarce", "plentiful", "noisy"]'::jsonb, 1, null, 'In the dry season water is hard to find, which means it is scarce.', 'published', 'import', now()),
('rwl1b_008', 'rw', 1, 'Craft and Structure', 'Words in Context', 'The students collected survey results and recycling data to ____ the principal to add recycling bins to every classroom.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["persuade", "warn", "ignore", "confuse"]'::jsonb, 0, null, 'The students gathered facts to convince the principal, which is what persuade means.', 'published', 'import', now()),
('rwl1b_009', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'The wood frog has an unusual way of surviving winter. As temperatures drop, up to two-thirds of the water in its body freezes, and its heart stops beating. When spring arrives, the frog thaws, its heart starts again, and it hops away.', null, 'Which choice best states the main purpose of the text?', '["To argue that frogs make good pets", "To explain how ponds form", "To describe how a particular animal survives cold winters", "To compare frogs and toads"]'::jsonb, 2, null, 'The text explains how the wood frog freezes and thaws to survive winter.', 'published', 'import', now()),
('rwl1b_010', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'Why do leaves change color in the fall? During spring and summer, leaves are full of chlorophyll, a green substance that helps plants make food. In autumn, as days grow shorter, trees stop making chlorophyll. The green fades, revealing yellow and orange colors that were in the leaves all along.', null, 'Which choice best describes the function of the first sentence in the overall structure of the text?', '["It gives the final conclusion of the text", "It introduces a question that the rest of the text answers", "It describes a person mentioned later", "It disagrees with an idea stated later"]'::jsonb, 1, null, 'The first sentence asks why leaves change color, and the rest of the text explains why.', 'published', 'import', now()),
('rwl1b_011', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'In 1815, Mount Tambora in Indonesia erupted, sending huge clouds of ash high into the sky. The ash spread around the world and blocked some sunlight. The next year was so cold in parts of Europe and North America that it became known as "the year without a summer," and many crops failed.', null, 'Which choice best describes the overall structure of the text?', '["It lists steps for completing a project", "It gives two opinions and then chooses one", "It describes an event and then explains its effects", "It describes a place and then a person who lived there"]'::jsonb, 2, null, 'The text describes the eruption and then explains its effects on weather around the world.', 'published', 'import', now()),
('rwl1b_012', 'rw', 1, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Recess gives students time to run, play, and make friends. These activities help children stay healthy and build social skills.

Text 2
Teachers in one study noticed that students paid closer attention to lessons after they had time to play outside. Breaks for play may help students learn, not just stay active.', null, 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?', '["By claiming that students do not enjoy recess", "By arguing that recess should be replaced with more class time", "By saying that recess has no effect on students", "By agreeing that recess is valuable and adding that it also helps students focus in class"]'::jsonb, 3, null, 'Both authors support recess. Text 2 adds a further benefit: better focus afterward.', 'published', 'import', now()),
('rwl1b_013', 'rw', 1, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Millions of tons of plastic enter the ocean each year. Floating plastic can harm sea turtles, seabirds, and fish that mistake it for food.

Text 2
Engineers have designed floating barriers that use ocean currents to gather plastic into one area, where boats can scoop it up and bring it to shore for recycling.', null, 'Which choice best describes how the two texts are related?', '["Text 1 explains the solution that Text 2 criticizes", "Text 2 argues that the problem in Text 1 does not exist", "Both texts describe the same historical event", "Text 2 describes a solution to the problem presented in Text 1"]'::jsonb, 3, null, 'Text 1 describes plastic waste in the ocean; Text 2 describes a device built to collect it.', 'published', 'import', now()),
('rwl1b_014', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'Hummingbirds can do something few other birds can: hover in place and even fly backward. Their wings beat up to 80 times per second, and their shoulder joints let their wings rotate in a figure-eight pattern. This lets them stay still in the air while they drink nectar from flowers.', null, 'Which choice best states the main idea of the text?', '["Hummingbirds have special features that let them hover and fly in unusual ways", "Hummingbirds eat only insects", "Hummingbirds migrate farther than any other bird", "Hummingbirds are the smallest birds in the world"]'::jsonb, 0, null, 'The text explains how the hummingbird''s fast wings and flexible shoulders let it hover and fly backward.', 'published', 'import', now()),
('rwl1b_015', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'At the 1936 Summer Olympics in Berlin, American runner and long jumper Jesse Owens won four gold medals, in the 100 meters, 200 meters, long jump, and 4 × 100 meter relay. His victories made him one of the most famous athletes in the world.', null, 'According to the text, what did Jesse Owens accomplish at the 1936 Olympics?', '["He set a record for the high jump", "He won a single silver medal", "He coached the US track team", "He won four gold medals"]'::jsonb, 3, null, 'The text states that Owens won four gold medals in Berlin.', 'published', 'import', now()),
('rwl1b_016', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'The items people toss into recycling bins can have surprising second lives. Aluminum cans can be melted and made into new cans in as little as two months. Paper can become cardboard boxes, and some plastic bottles are turned into fleece jackets.', null, 'Which choice best states the main idea of the text?', '["Many common materials can be recycled into new products", "Recycling is more expensive than throwing things away", "Glass cannot be recycled", "Most cities do not collect recycling"]'::jsonb, 0, null, 'The text gives examples of materials (aluminum, paper, plastic) that become new products.', 'published', 'import', now()),
('rwl1b_017', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'In 2007, a powerful tornado destroyed most of Greensburg, Kansas. Instead of rebuilding the town exactly as it was, residents decided to construct energy-efficient buildings that use wind power and natural light. They hoped the new design would save money on energy and help the town recover.', null, 'Based on the text, why did the town of Greensburg rebuild with "green" buildings?', '["To save energy and make the town stronger after a tornado", "To meet a law that required it", "To attract more tourists to the town", "Because the old buildings were too small"]'::jsonb, 0, null, 'After the tornado destroyed the town, residents chose to rebuild with energy-efficient buildings.', 'published', 'import', now()),
('rwl1b_018', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A student made a table of animals'' top running speeds. The table shows that ____.', '{"h": ["Animal", "Top speed (mph)"], "r": [["Cheetah", "70"], ["Lion", "50"], ["Horse", "55"], ["Elephant", "25"]]}'::jsonb, 'Which choice most effectively uses data from the table to complete the statement?', '["the elephant is faster than the horse", "the lion is faster than the cheetah", "the cheetah is the fastest of the animals listed", "all of the animals run at the same speed"]'::jsonb, 2, null, 'The cheetah''s top speed (70 mph) is greater than every other animal''s in the table.', 'published', 'import', now()),
('rwl1b_019', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A student claims that a new reading app helps students improve their reading skills.', null, 'Which finding would most directly support the student''s claim?', '["The app was released last year", "The reading app has colorful pictures", "Some students like reading on paper better", "Students who used the new reading app improved their reading scores more than students who did not"]'::jsonb, 3, null, 'The claim is that the app helps reading, so better improvement by app users supports it directly.', 'published', 'import', now()),
('rwl1b_020', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'In a short story, a character named Marcus is nervous before his first concert.', null, 'Which quotation from the story best shows that Marcus is nervous?', '["\"Marcus had played the violin since he was six.\"", "\"Marcus''s hands shook as he tuned his violin, and he kept glancing at the crowded seats.\"", "\"Marcus''s teacher smiled from the front row.\"", "\"The concert hall had red velvet curtains.\""]'::jsonb, 1, null, 'Shaking hands and glancing at the crowd show nervousness.', 'published', 'import', now()),
('rwl1b_021', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A librarian claims that the library is busiest in the summer.', '{"h": ["Month", "Books lent"], "r": [["March", "1,400"], ["May", "1,550"], ["July", "2,100"], ["October", "1,300"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the claim?', '["The library lent books every month", "The library is open six days a week", "The library lent 1,400 books in March", "The library lent 2,100 books in July, more than in any other month shown"]'::jsonb, 3, null, 'The claim is that summer is the busiest time; July has the highest number in the table.', 'published', 'import', now()),
('rwl1b_022', 'rw', 1, 'Information and Ideas', 'Inferences', 'When Theo walked into the kitchen, the oven was still warm, a tray of cookies sat cooling on the counter, and the whole house smelled of cinnamon. Theo realized that ____', null, 'Which choice most logically completes the text?', '["the cookies had probably been baked recently", "the cookies were bought at a store last month", "no one in the house liked cookies", "the oven had been broken for weeks"]'::jsonb, 0, null, 'A warm oven, a cooling tray, and the smell of cookies are clues that they were just baked.', 'published', 'import', now()),
('rwl1b_023', 'rw', 1, 'Information and Ideas', 'Inferences', 'A tree usually adds one growth ring each year. Scientists studying bristlecone pines in California counted more than 4,000 rings in some of the trees'' trunks. This suggests that ____', null, 'Which choice most logically completes the text?', '["the trees are not real", "the trees will soon stop growing", "the trees are likely very old", "the trees were planted last year"]'::jsonb, 2, null, 'Many rings means many years of growth, so trees with thousands of rings are very old.', 'published', 'import', now()),
('rwl1b_024', 'rw', 1, 'Information and Ideas', 'Inferences', 'Before the city added a crosswalk with flashing lights at Oak and Fifth Streets, there were about twelve accidents there each year. In the two years since it was added, there have been only two accidents in total. These numbers suggest that ____', null, 'Which choice most logically completes the text?', '["more cars now use the street", "the crosswalk should be removed", "the new crosswalk has made the intersection safer", "drivers ignore the new signal"]'::jsonb, 2, null, 'Accidents dropped sharply after the crosswalk was added, suggesting it improved safety.', 'published', 'import', now()),
('rwl1b_025', 'rw', 1, 'Information and Ideas', 'Inferences', 'A gardener planted two groups of wildflower seeds. She kept the first group in a refrigerator for a month before planting; nearly all of them sprouted. The second group, kept at room temperature, barely sprouted at all. The results suggest that ____', null, 'Which choice most logically completes the text?', '["the seeds were damaged", "the seeds may need cold weather before they can sprout", "the plant can grow only in deserts", "the seeds need darkness to grow"]'::jsonb, 1, null, 'Seeds kept cold sprouted while warm seeds did not, so cold seems to be needed.', 'published', 'import', now()),
('rwl1b_026', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'Iceland has more than 30 active ____ have erupted within the last few decades.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["volcanoes, some", "volcanoes and, some", "volcanoes. Some", "volcanoes some"]'::jsonb, 2, null, 'These are two complete sentences, so a period separates them.', 'published', 'import', now()),
('rwl1b_027', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'Every beekeeper needs a few basic ____ a protective suit, a smoker, and a hive tool.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["tools, a", "tools; a", "tools a", "tools: a"]'::jsonb, 3, null, 'A colon introduces the list after a complete sentence.', 'published', 'import', now()),
('rwl1b_028', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'Frida ____ Mexican painter, is famous for her colorful self-portraits.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Kahlo, a", "Kahlo. A", "Kahlo; a", "Kahlo a"]'::jsonb, 0, null, '"A Mexican painter…" renames Frida Kahlo and is set off with commas.', 'published', 'import', now()),
('rwl1b_029', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The bus to the science museum arrived thirty minutes ____ the students still had time to see every exhibit.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["late; but,", "late but", "late. But,", "late, but"]'::jsonb, 3, null, 'A comma goes before "but" when it joins two complete sentences.', 'published', 'import', now()),
('rwl1b_030', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'Chess is a strategy ____ that has been played for more than 1,500 years.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["game,", "game", "game;", "game:"]'::jsonb, 1, null, 'No punctuation is needed between "game" and "that," which begins essential information about the game.', 'published', 'import', now()),
('rwl1b_031', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The farmers market is open every ____ it closes for the winter in November.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Saturday;", "Saturday:", "Saturday,", "Saturday"]'::jsonb, 0, null, 'A semicolon joins the two complete sentences.', 'published', 'import', now()),
('rwl1b_032', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The tallest trees in the national park ____ more than 300 feet high.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are", "has been", "was", "is"]'::jsonb, 0, null, 'The subject "the tallest trees" is plural, so the verb is "are."', 'published', 'import', now()),
('rwl1b_033', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'After practicing for months, the girl finally landed ____ first back handspring at the gymnastics meet.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["their", "its", "her", "his"]'::jsonb, 2, null, 'The pronoun refers to "the girl," so "her" is correct.', 'published', 'import', now()),
('rwl1b_034', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'In 1876, Alexander Graham Bell ____ the telephone.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is inventing", "invented", "invents", "will invent"]'::jsonb, 1, null, 'The sentence describes an event in 1876, so the past tense is needed.', 'published', 'import', now()),
('rwl1b_035', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The ____ section of the library has beanbag chairs and a reading tent.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["children''s", "child''s", "childrens''", "childrens"]'::jsonb, 0, null, '"Children" is already plural, so its possessive is "children''s."', 'published', 'import', now()),
('rwl1b_036', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'Neither my brother nor my sister ____ the piano, but both enjoy singing.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["play", "playing", "have played", "plays"]'::jsonb, 3, null, '"Neither my brother nor my sister": the verb agrees with "sister" (singular), so "plays."', 'published', 'import', now()),
('rwl1b_037', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The shelter workers fed the puppies and then gave ____ fresh blankets.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["them", "him", "it", "her"]'::jsonb, 0, null, 'The pronoun refers to "the puppies" (plural), so "them" is correct.', 'published', 'import', now()),
('rwl1b_038', 'rw', 1, 'Expression of Ideas', 'Transitions', 'A cheetah can sprint at up to 70 miles per hour. ____ a three-toed sloth moves so slowly that it might travel only about 40 yards in a day.', null, 'Which choice completes the text with the most logical transition?', '["As a result,", "In contrast,", "For example,", "Similarly,"]'::jsonb, 1, null, 'The second sentence describes the opposite of the first (fast vs. slow), so "In contrast" fits.', 'published', 'import', now()),
('rwl1b_039', 'rw', 1, 'Expression of Ideas', 'Transitions', 'To plant a tree, first dig a hole twice as wide as the roots. Next, place the tree in the hole and fill it with soil. ____ water the tree deeply.', null, 'Which choice completes the text with the most logical transition?', '["For instance,", "However,", "Finally,", "Similarly,"]'::jsonb, 2, null, 'This is the last step in a sequence, so "Finally" fits.', 'published', 'import', now()),
('rwl1b_040', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Sleep helps the brain store new memories and recover from the day. ____ students who get enough sleep often find it easier to focus in class.', null, 'Which choice completes the text with the most logical transition?', '["However,", "For example,", "Meanwhile,", "Therefore,"]'::jsonb, 3, null, 'Getting more sleep leads to better focus, so a result word fits.', 'published', 'import', now()),
('rwl1b_041', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Riding a bicycle to work is good exercise. ____ it saves money on gas and parking.', null, 'Which choice completes the text with the most logical transition?', '["However,", "In addition,", "On the other hand,", "Instead,"]'::jsonb, 1, null, 'The second sentence adds another benefit of bicycles.', 'published', 'import', now()),
('rwl1b_042', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Some plants get extra nutrients by trapping insects. ____ the Venus flytrap snaps its leaves shut when an insect touches tiny hairs inside them.', null, 'Which choice completes the text with the most logical transition?', '["Instead,", "For example,", "In conclusion,", "However,"]'::jsonb, 1, null, 'The second sentence gives an example of a plant that eats insects.', 'published', 'import', now()),
('rwl1b_043', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Amazon River is about 4,000 miles long.
• It begins in the Andes Mountains of Peru.
• It flows east across South America into the Atlantic Ocean.
• It carries more water than any other river.
• More than 3,000 kinds of fish live in it.', null, 'The student wants to explain where the Amazon River flows. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Amazon River flows about 4,000 miles across South America, from the Andes Mountains in Peru to the Atlantic Ocean.", "The Amazon rainforest is the largest rainforest on Earth.", "The Amazon River carries more water than any other river.", "More than 3,000 kinds of fish live in the Amazon."]'::jsonb, 0, null, 'Only this choice describes the river''s path.', 'published', 'import', now()),
('rwl1b_044', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Louis Braille was born in France in 1809.
• He lost his sight in an accident at age three.
• He attended a school for blind students in Paris.
• He created a system of raised dots that can be read by touch.
• The system is now used around the world.', null, 'The student wants to describe what Louis Braille created. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Louis Braille created a reading system of raised dots that people who are blind can read with their fingertips.", "Louis Braille went to a school in Paris.", "Louis Braille was born in France in 1809.", "Louis Braille lost his sight in an accident as a young child."]'::jsonb, 0, null, 'Only this choice explains what Braille created.', 'published', 'import', now()),
('rwl1b_045', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Alligators and crocodiles are both reptiles.
• Both have strong jaws.
• Alligators have wide, U-shaped snouts.
• Crocodiles have narrower, V-shaped snouts.
• Alligators live mostly in the southeastern United States and China.', null, 'The student wants to show a difference between the two animals. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Crocodiles and alligators both have strong jaws.", "Alligators live in the southeastern United States.", "Alligators and crocodiles are both reptiles.", "Alligators have wide, U-shaped snouts, while crocodiles have narrower, V-shaped snouts."]'::jsonb, 3, null, 'Only this choice states a difference between the animals.', 'published', 'import', now()),
('rwl2b_001', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Lichens can ____ conditions that would kill most other living things, surviving on bare rock in deserts, on mountaintops, and even in Antarctica.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["endure", "predict", "celebrate", "avoid"]'::jsonb, 0, null, 'The plants survive harsh conditions, which is what endure means.', 'published', 'import', now()),
('rwl2b_002', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Bamboo is a remarkably ____ material. Builders use it for scaffolding and floors, designers turn it into furniture, and manufacturers even spin its fibers into cloth.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["limited", "fragile", "outdated", "versatile"]'::jsonb, 3, null, 'A material that can be used in many different ways is versatile.', 'published', 'import', now()),
('rwl2b_003', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Pay phones were once found on nearly every city corner. As mobile phones spread, however, they became largely ____, and most cities removed them.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["obsolete", "valuable", "experimental", "popular"]'::jsonb, 0, null, 'Technology that has been replaced and is no longer used is obsolete.', 'published', 'import', now()),
('rwl2b_004', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Dolores Huerta spent decades as a tireless ____ for farmworkers, organizing boycotts and lobbying lawmakers for safer working conditions and fair pay.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["observer", "advocate", "victim", "opponent"]'::jsonb, 1, null, 'Someone who campaigns in favor of a cause is an advocate.', 'published', 'import', now()),
('rwl2b_005', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The first round of tests on the new fertilizer was ____: some plots of corn grew more than usual, but others grew less, leaving researchers unsure whether the product had any effect.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["decisive", "unanimous", "fraudulent", "inconclusive"]'::jsonb, 3, null, 'The results did not settle the question, so they were inconclusive.', 'published', 'import', now()),
('rwl2b_006', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The coach worked to cultivate a sense of trust among her players, encouraging them to support one another during difficult games.', null, 'As used in the text, what does the word "cultivate" most nearly mean?', '["develop", "plant", "harvest", "plow"]'::jsonb, 0, null, 'The coach helps players build teamwork, so "cultivate" means develop.', 'published', 'import', now()),
('rwl2b_007', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Tropical rainforests are among the most ____ ecosystems on Earth. A single hectare of forest in Ecuador may contain more than 400 different kinds of trees.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["temporary", "diverse", "uniform", "isolated"]'::jsonb, 1, null, 'A forest with thousands of different species has great variety, which is what diverse means.', 'published', 'import', now()),
('rwl2b_008', 'rw', 2, 'Craft and Structure', 'Words in Context', 'In her memoir, the astronaut is unusually ____ about her early setbacks, openly describing the two times she was rejected by NASA before finally being selected.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["brief", "candid", "evasive", "rehearsed"]'::jsonb, 1, null, 'The author speaks openly about her failures, which is what candid means.', 'published', 'import', now()),
('rwl2b_009', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Vanilla is one of the world''s most popular flavors, yet it is notoriously hard to produce. Each vanilla orchid flower opens for only a single day, and outside its native Mexico, the plant has no natural pollinators. Farmers in places such as Madagascar must pollinate every flower by hand, using a thin stick.', null, 'Which choice best states the main purpose of the text?', '["To explain why a familiar food is surprisingly difficult to grow", "To describe the history of ice cream", "To persuade readers to eat more vanilla", "To compare vanilla with chocolate"]'::jsonb, 0, null, 'The text explains how vanilla flowers must be pollinated by hand and bloom only briefly, making the crop difficult to grow.', 'published', 'import', now()),
('rwl2b_010', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Leafcutter ants carry pieces of leaves many times their own weight back to their nests. They don''t eat the leaves; instead, they chew them into a paste on which they grow a fungus that serves as the colony''s food. Some colonies contain millions of ants.', null, 'Which choice best describes the function of the second sentence in the overall structure of the text?', '["It contradicts the first sentence", "It explains the reason for the behavior described in the first sentence", "It gives a second example of the same behavior", "It describes what happened next in the story"]'::jsonb, 1, null, 'The first sentence describes ants carrying leaves; the second explains why: they use them to grow fungus.', 'published', 'import', now()),
('rwl2b_011', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Many early inventors tried to fly by building machines with flapping wings like a bird''s. These designs failed because human muscles are far too weak to power them. Wilbur and Orville Wright took a different approach, focusing on how to control a fixed-wing aircraft, and in 1903 they made the first powered, controlled airplane flights.', null, 'Which choice best describes the overall structure of the text?', '["It lists several inventors in alphabetical order", "It describes an early idea, explains why it failed, and then presents a later success", "It argues that airplanes are unsafe", "It compares birds and airplanes"]'::jsonb, 1, null, 'The text moves from early flapping-wing machines, to why they failed, to the Wright brothers'' success.', 'published', 'import', now()),
('rwl2b_012', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Researchers placed small speakers playing recorded bee buzzing near evening primrose flowers. To many scientists'' surprise, within minutes the flowers produced sweeter nectar, suggesting that the plants can respond to the sound of approaching pollinators.', null, 'Which choice best describes the function of the phrase "to many scientists'' surprise" in the text?', '["It suggests that the study was poorly designed", "It shows that scientists predicted the result", "It signals that the finding went against what researchers expected", "It introduces a scientist''s name"]'::jsonb, 2, null, 'The phrase indicates the result was unexpected.', 'published', 'import', now()),
('rwl2b_013', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Some sunscreen chemicals have been linked to damage in coral reefs. Swimmers who want to protect reefs should therefore simply choose sunscreens labeled "natural" or "plant-based."

Text 2
Labels such as "natural" are not regulated. Recent lab studies found that certain plant oils used in sunscreens can also stress coral. Swimmers may protect reefs best by wearing protective clothing.', null, 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1?', '["By stating that coral reefs are not in danger", "By agreeing completely with the claim", "By arguing that the claim ignores evidence that plant-based ingredients can also be harmful", "By arguing that all sunscreens should be banned"]'::jsonb, 2, null, 'Text 1 says natural sunscreens are safe for reefs; Text 2 says some plant-based ingredients may also harm coral.', 'published', 'import', now()),
('rwl2b_014', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
In trials of a four-day workweek, employees reported less stress and more time with family, and many companies saw no drop in output.

Text 2
The trials mostly involved office jobs. For businesses that must stay open around the clock, such as hospitals, a shorter week might require hiring more staff, which could be costly.', null, 'Which choice best describes how the authors of the two texts view the four-day workweek?', '["Both texts focus only on the effects on students", "Both texts argue that the four-day week should be required by law", "Text 1 emphasizes benefits for workers, while Text 2 raises concerns about some kinds of businesses", "Text 1 opposes the four-day week, while Text 2 supports it"]'::jsonb, 2, null, 'Text 1 discusses workers'' well-being; Text 2 points out difficulties for businesses like hospitals.', 'published', 'import', now()),
('rwl2b_015', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Mangrove trees grow along tropical coastlines, their tangled roots rising out of the salty water. These roots slow incoming waves, reducing damage from storms, and shelter young fish and crabs. Yet in recent decades, large areas of mangrove forest have been cleared to make room for shrimp farms and coastal development.', null, 'Which choice best states the main idea of the text?', '["Mangroves are the tallest trees in the tropics", "Mangrove trees can grow only in fresh water", "Mangrove forests protect coastlines and support wildlife, but they are disappearing", "Coastal cities have stopped building near the shore"]'::jsonb, 2, null, 'The text explains mangroves'' benefits and then notes that many have been cleared.', 'published', 'import', now()),
('rwl2b_016', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Hedy Lamarr was a famous film actress in the 1940s, but she was also an inventor. During World War II, she and composer George Antheil patented a system of "frequency hopping" that switched radio signals among many channels to prevent enemies from jamming them. Similar ideas were later used in technologies such as Wi-Fi and Bluetooth.', null, 'According to the text, how did Hedy Lamarr contribute to modern technology?', '["She designed the first cell phone", "She built the first television", "She helped invent a method of switching radio frequencies that later influenced wireless communication", "She created a computer programming language"]'::jsonb, 2, null, 'The text says her frequency-hopping invention later influenced technologies such as Wi-Fi and Bluetooth.', 'published', 'import', now()),
('rwl2b_017', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Bike-sharing programs, which let riders unlock a bicycle at one station and leave it at another, now operate in hundreds of cities worldwide. Riders say the bikes are cheaper than taxis, faster than walking, and easy to use for short trips. Some cities have added electric bikes to make hilly routes easier.', null, 'Which choice best states the main idea of the text?', '["Bicycles are more expensive than cars", "Shared bike programs have become popular in cities because they are convenient and inexpensive", "Most people prefer driving to biking", "Bike programs are found only in Europe"]'::jsonb, 1, null, 'The text describes how bike-share programs spread and why riders like them.', 'published', 'import', now()),
('rwl2b_018', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'The following text is adapted from a novel.

As the train pulled away, Rosa pressed her forehead against the window and watched the farm shrink into a green smudge. In her bag were letters of welcome from the music school and a map of the city she had dreamed about for years. Still, she kept turning back, as if she might catch one last glimpse of her mother waving by the gate.', null, 'Based on the text, what is the narrator''s main feeling as she leaves home?', '["Fear of the dark", "Excitement mixed with sadness", "Pure anger", "Complete boredom"]'::jsonb, 1, null, 'She is eager for the city but sad to leave her family and the farm.', 'published', 'import', now()),
('rwl2b_019', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A student claims that cities with more tree cover tend to have cooler summers.', '{"h": ["City", "Tree cover (%)", "Avg. summer temperature (°F)"], "r": [["A", "40", "87"], ["B", "30", "89"], ["C", "25", "91"], ["D", "10", "95"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the claim?', '["All four cities had some tree cover", "Cities with more tree cover had lower average summer temperatures, ranging from 87°F with 40% cover to 95°F with 10% cover", "City A had an average summer temperature of 87°F", "City D had 25% tree cover"]'::jsonb, 1, null, 'The claim links more tree cover with cooler temperatures; this choice describes that pattern across the cities.', 'published', 'import', now()),
('rwl2b_020', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'Researchers hypothesized that dogs can understand human pointing gestures. In an experiment, a treat was hidden under one of two cups, and a researcher sometimes pointed to the correct cup.', null, 'Which finding, if true, would most directly support the researchers'' hypothesis?', '["Dogs looked at the correct cup more often when a person pointed to it than when no one pointed", "Some dogs are better at fetching than others", "Dogs prefer some kinds of treats to others", "Wolves live in packs in the wild"]'::jsonb, 0, null, 'The hypothesis is that dogs understand pointing, so evidence that pointing changes their choices supports it.', 'published', 'import', now()),
('rwl2b_021', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'In a speech at a park''s opening ceremony, the mayor claimed that ordinary citizens can make a real difference in their communities.', null, 'Which quotation from the speech best supports the speaker''s claim that ordinary citizens can make a difference?', '["\"Parking is difficult downtown on weekends.\"", "\"Our city was founded more than two hundred years ago.\"", "\"The weather today is perfect for a celebration.\"", "\"The park we stand in today exists because a handful of neighbors refused to let it become a parking lot.\""]'::jsonb, 3, null, 'Only this quotation shows ordinary people creating a positive change.', 'published', 'import', now()),
('rwl2b_022', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'The table shows the share of households in a region with home internet access. It shows that ____.', '{"h": ["Year", "Households with internet (%)"], "r": [["2000", "42"], ["2010", "71"], ["2020", "93"]]}'::jsonb, 'Which choice best uses data from the table to complete the statement?', '["internet access decreased after 2010", "every household had internet access by 2000", "the percentage of households with internet access more than doubled between 2000 and 2020", "internet access stayed the same between 2010 and 2020"]'::jsonb, 2, null, 'Access rose from 42% in 2000 to 93% in 2020, more than double.', 'published', 'import', now()),
('rwl2b_023', 'rw', 2, 'Information and Ideas', 'Inferences', 'Art historians examining an unsigned painting found that its purple paint contains mauveine, a dye first created by chemist William Perkin in 1856. The dye was not widely available to artists until around 1860. This suggests that ____', null, 'Which choice most logically completes the text?', '["purple paint was common in ancient times", "the painting is a copy of an older work", "the artist never used the color purple", "the painting was likely made after 1860"]'::jsonb, 3, null, 'The painting contains a dye that didn''t exist until 1856 and wasn''t sold widely until about 1860, so it must have been made later.', 'published', 'import', now()),
('rwl2b_024', 'rw', 2, 'Information and Ideas', 'Inferences', 'Divers monitoring a reef noticed that its coral turned white each time the water temperature rose above 30°C for several weeks. When temperatures dropped again, much of the coral slowly regained its color. The divers concluded that ____', null, 'Which choice most logically completes the text?', '["the coral is growing faster than usual", "the coral''s color depends on the time of day", "the coral''s color change is a response to warmer water", "the coral prefers cooler water than fish do"]'::jsonb, 2, null, 'The coral turned white only when the water got warmer, and recovered when it cooled.', 'published', 'import', now()),
('rwl2b_025', 'rw', 2, 'Information and Ideas', 'Inferences', 'Two classes took the same math test in September and again in December. Between tests, one class learned with a new hands-on method, while the other used its usual textbook lessons. Scores rose sharply in the first class but stayed about the same in the second. This suggests that ____', null, 'Which choice most logically completes the text?', '["the test was easier the second time", "students in both classes studied less", "the teacher did not use the new method", "the students'' improvement was probably due to the new teaching method"]'::jsonb, 3, null, 'Only the class using the new method improved; the other class, with the same test, did not.', 'published', 'import', now()),
('rwl2b_026', 'rw', 2, 'Information and Ideas', 'Inferences', 'At an ancient stone circle, archaeologists found that two large stones frame the exact point on the horizon where the sun rises on the summer solstice, the longest day of the year. The alignment is too precise to be accidental. This suggests that ____', null, 'Which choice most logically completes the text?', '["the stones were moved there recently", "the ancient people of the region may have tracked the seasons", "the builders did not know about the sun", "the site was used only at night"]'::jsonb, 1, null, 'Stones lined up with the solstice sunrise suggest the builders paid attention to the sun''s yearly cycle.', 'published', 'import', now()),
('rwl2b_027', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Archaeologists have found pots of ____ some of it, buried in Egyptian tombs thousands of years ago, was still edible.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["honey,", "honey", "honey:", "honey;"]'::jsonb, 3, null, 'The two complete sentences are joined with a semicolon. A comma alone would create a comma splice.', 'published', 'import', now()),
('rwl2b_028', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Marie Van Brittan Brown, a nurse and ____ the patent for one of the first home security systems, created in 1966.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["inventor, holds", "inventor; holds", "inventor. Holds", "inventor holds"]'::jsonb, 0, null, 'The phrase "a nurse and inventor" renames Brown and is set off with commas on both sides.', 'published', 'import', now()),
('rwl2b_029', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The monarch butterfly''s ____ can cover up to 3,000 miles, from Canada to central Mexico.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["migration,", "migration", "migration;", "migration:"]'::jsonb, 1, null, 'No punctuation is needed between the subject ("the monarch butterfly''s migration") and the verb.', 'published', 'import', now()),
('rwl2b_030', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Some deserts receive most of their rain in short, violent ____ others get only light drizzle a few times each year.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["storms, while", "storms; while", "storms. While", "storms while,"]'::jsonb, 0, null, '"While" begins a dependent clause that contrasts with the main clause and is joined with a comma.', 'published', 'import', now()),
('rwl2b_031', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'In a 2015 interview, the author ____ to read changed my life."', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["said. \"Learning", "said; \"Learning", "said \"Learning", "said, \"Learning"]'::jsonb, 3, null, 'A comma comes before a direct quotation that follows a verb such as "said."', 'published', 'import', now()),
('rwl2b_032', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The Antikythera mechanism—an ancient Greek ____ was used to predict the positions of the sun, moon, and planets.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["machine—", "machine,", "machine", "machine;"]'::jsonb, 0, null, 'The added information began with a dash, so it must close with a dash.', 'published', 'import', now()),
('rwl2b_033', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Each of the national parks in Utah ____ its own unique rock formations.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["has", "are", "have", "were"]'::jsonb, 0, null, 'The subject "each" is singular, so the verb is "has."', 'published', 'import', now()),
('rwl2b_034', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Sea otters hold hands while sleeping on the water. This way, ____ do not drift apart.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["it", "he", "she", "they"]'::jsonb, 3, null, 'The pronoun refers to "sea otters," which is plural.', 'published', 'import', now()),
('rwl2b_035', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'By next spring, the construction crew ____ the new bridge across the river.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["finishes", "has finished", "finished", "will have finished"]'::jsonb, 3, null, 'The action will be completed before a future point (by next spring), so "will have finished" is correct.', 'published', 'import', now()),
('rwl2b_036', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The results of the survey on student lunch preferences ____ shared with the school board last week.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were", "is", "has been", "was"]'::jsonb, 0, null, 'The subject "the results" is plural, so the verb is "were."', 'published', 'import', now()),
('rwl2b_037', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Visitors to the lake can spend their days hiking, kayaking, and ____.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["swims", "swimming", "swim", "to swimming"]'::jsonb, 1, null, 'The list is parallel: hiking, kayaking, and swimming.', 'published', 'import', now()),
('rwl2b_038', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Zaha Hadid was an architect ____ bold, curving designs changed modern architecture.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["who", "who''s", "whose", "whom"]'::jsonb, 2, null, '"Whose" shows possession (the architect''s designs).', 'published', 'import', now()),
('rwl2b_039', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Emperor penguins breed during the Antarctic winter, when temperatures can fall below −40°F and winds blow at 100 miles per hour. ____ huge colonies successfully raise their chicks every year.', null, 'Which choice completes the text with the most logical transition?', '["Likewise,", "Because of this,", "Despite this,", "For example,"]'::jsonb, 2, null, 'The penguins thrive even though the conditions are harsh, so a contrast transition fits.', 'published', 'import', now()),
('rwl2b_040', 'rw', 2, 'Expression of Ideas', 'Transitions', 'The new law changes how schools serve lunch. ____ it requires that every meal include at least one fruit and one vegetable.', null, 'Which choice completes the text with the most logical transition?', '["However,", "Nevertheless,", "Meanwhile,", "Specifically,"]'::jsonb, 3, null, 'The second sentence gives details that make the first sentence more precise.', 'published', 'import', now()),
('rwl2b_041', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Sea otters eat large numbers of sea urchins, which feed on kelp. When sea otters were hunted almost to extinction along the Pacific coast, urchin populations exploded. ____ many kelp forests were destroyed.', null, 'Which choice completes the text with the most logical transition?', '["As a result,", "Similarly,", "For instance,", "In contrast,"]'::jsonb, 0, null, 'Losing the sea otters caused urchins to increase, so a result transition fits.', 'published', 'import', now()),
('rwl2b_042', 'rw', 2, 'Expression of Ideas', 'Transitions', 'In the 1800s, many people in American cities kept pigs and chickens in their backyards, and animals often roamed the streets. ____ most cities limit or ban farm animals within city limits.', null, 'Which choice completes the text with the most logical transition?', '["Today,", "In contrast,", "Previously,", "As a result,"]'::jsonb, 0, null, 'The text moves from the past to the present, so "Today" fits.', 'published', 'import', now()),
('rwl2b_043', 'rw', 2, 'Expression of Ideas', 'Transitions', 'The leafy sea dragon has frond-like fins that make it look like floating seaweed. ____ the stick insect resembles a twig so closely that predators often overlook it.', null, 'Which choice completes the text with the most logical transition?', '["However,", "Instead,", "Likewise,", "Otherwise,"]'::jsonb, 2, null, 'Both sentences describe animals using the same strategy (camouflage), so "Likewise" fits.', 'published', 'import', now()),
('rwl2b_044', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Sahara is in northern Africa.
• It covers about 3.6 million square miles.
• The United States covers about 3.8 million square miles.
• Temperatures can exceed 120°F.
• Oases provide water for plants and people.', null, 'The student wants to emphasize the size of the Sahara Desert. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Temperatures in the Sahara can exceed 120°F.", "Covering about 3.6 million square miles, the Sahara is nearly as large as the entire United States.", "The Sahara is located in northern Africa.", "The Sahara has some oases where plants grow."]'::jsonb, 1, null, 'Only this choice focuses on the desert''s size, using a comparison that makes it vivid.', 'published', 'import', now()),
('rwl2b_045', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Sylvia Earle was born in New Jersey in 1935.
• She is a marine biologist and explorer.
• In 1979, she walked untethered on the ocean floor about 1,250 feet deep, a record for a woman.
• This feat earned her the nickname "Her Deepness."
• She was the first woman to serve as chief scientist of NOAA.', null, 'The student wants to explain why Sylvia Earle is known as "Her Deepness." Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Sylvia Earle was the first woman to serve as chief scientist of NOAA.", "Sylvia Earle was born in New Jersey in 1935.", "Sylvia Earle has written many books about the ocean.", "Sylvia Earle earned the nickname \"Her Deepness\" after she walked untethered on the ocean floor at a depth of about 1,250 feet, a record for a woman."]'::jsonb, 3, null, 'Only this choice connects her nickname to her deep-sea achievement.', 'published', 'import', now()),
('rwl2b_046', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
